const out = [];
for (const it of $input.all()) {
  const r = it.json.r;
  const lista = Array.isArray(r) ? r : ((r && r._tg) || []);
  for (const m of lista) {
    if (!m || !m.chat_id || !m.text) continue;
    const body = { chat_id: String(m.chat_id), text: String(m.text).slice(0, 4000), parse_mode: 'HTML', disable_web_page_preview: true };
    if (m.url && /^https:\/\//.test(m.url)) body.reply_markup = { inline_keyboard: [[{ text: m.boton || 'Abrir', url: m.url }]] };
    out.push({ json: { body } });
  }
}
return out;

