// Ventas web: guarda la página para abrirla sin internet. Siempre intenta primero bajar la versión nueva;
// solo usa la guardada si no hay conexión. Las llamadas a la base (ventas-api) nunca pasan por aquí.
const V = 'ventas-v40';
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', e => e.waitUntil((async () => { for (const k of await caches.keys()) if (k !== V) await caches.delete(k); await self.clients.claim(); })()));
self.addEventListener('fetch', e => {
  const r = e.request; if (r.method !== 'GET') return;
  const u = new URL(r.url); if (u.origin !== self.location.origin) return;
  const p = u.pathname.replace(/\/+$/, '');
  if (!/\/ventas(-logos)?$/.test(p)) return;
  e.respondWith(primeroRed(r, u.origin + p));
});
async function primeroRed(r, clave) {
  const c = await caches.open(V);
  try {
    const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), 7000);
    const res = await fetch(r, { signal: ctl.signal, cache: 'no-store' }); clearTimeout(t);
    if (res && res.ok) c.put(clave, res.clone());
    return res;
  } catch (err) {
    const m = await c.match(clave);
    if (m) return m;
    throw err;
  }
}

