// Panel del dueño: los mismos cálculos del "Cierre del día" y del reporte de cemento, en datos para la página web
const cfg = $('Panel · Configuración').first().json;
const r = $('Panel · Datos del día').first().json.r || {};
const k = $('Panel · KPIs del día').first().json.k || {};
const tin = (() => { try { return $('Panel · Tinacos atrasados').first().json.r || {}; } catch (e) { return {}; } })();
const cem = (() => { try { return $('Panel · Ventas de cemento').first().json.r || {}; } catch (e) { return {}; } })();
const N = v => Number(v || 0);
const pct = (a, b) => (b ? Math.round((a / b - 1) * 100) : null);
// ---- ventas y utilidad ----
const META = N((k.meta || {}).mensual) || N(cfg.meta_mensual);
const m = k.mes || {};
const metaDia = META && m.hab_totales ? META / m.hab_totales : 0;
const hoyV = N(k.hoy), prom = N(k.prom30);
const u = k.util_hoy || {};
const cob = u.venta_siva ? N(u.venta_con_costo) / N(u.venta_siva) : 0;
const utilHoy = u.venta_con_costo ? N(u.venta_con_costo) - N(u.costo) : null;
const margen = u.venta_con_costo ? utilHoy / N(u.venta_con_costo) : null;
const utilMes = m.venta_con_costo ? N(m.venta_con_costo) - N(m.costo) : null;
// ---- caja ----
const mov = r.mov || [];
const de = t => mov.filter(x => x.tdoc === t);
const suma = (arr, f = () => true) => arr.filter(f).reduce((s, x) => s + Math.abs(N(x.t)), 0);
const fondos = r.fondos || [];
const fondoIni = fondos.filter(x => x.tipo_movto === 'A').reduce((s, x) => s + N(x.efectivo), 0);
const esperado = fondoIni + suma(de('V'), x => x.efectivo) + suma(de('P'), x => x.efectivo) + suma(de('I'), x => x.efectivo)
  - suma(de('D'), x => x.efectivo) - suma(de('R'), x => x.efectivo);
const cierre = fondos.find(x => x.tipo_movto === 'C' && N(x.renglones) > 0);
const difCaja = cierre ? N(cierre.efectivo) - esperado : null;
const cobranzaHoy = suma(de('P')), creditoHoy = suma(de('V'), x => x.credito);
const TOL1 = 20, TOL2 = 100;
// ---- pedidos, pendientes, inventario ----
const ped = r.pedidos || {}, rem = r.remisiones || {};
const pe = (k.pend || {}).ped || {}, pr = (k.pend || {}).rem || {};
const totPend = ['b0', 'b1', 'b2', 'b3', 'hist'].reduce((s, b) => s + N(pe[b]), 0);
const invK = k.inv || {};
const cogsDia = invK.dias_venta_30d ? N(invK.costo_30d) / invK.dias_venta_30d : 0;
const diasInv = cogsDia ? Math.round(N(invK.valor) / cogsDia) : null;
const cobM = N(m.cobranza), credM = N(m.credito_otorgado);
// ---- semáforo (mismas reglas que Telegram) ----
const baseV = metaDia || prom;
const avance = baseV ? hoyV / baseV : null;
const color = (ok, mid) => ok ? 'verde' : mid ? 'amarillo' : 'rojo';
const semaforo = {
  ventas: avance === null ? 'gris' : color(avance >= 1, avance >= 0.85),
  caja: difCaja === null ? 'amarillo' : color(Math.abs(difCaja) <= TOL1, Math.abs(difCaja) <= TOL2),
  cobranza: credM === 0 && cobM === 0 ? 'gris' : color(cobM >= credM, cobM >= credM * 0.7),
  pedidos: N(pe.b3) > 0 || N(tin.n) > 0 ? 'rojo' : N(pe.b2) > 0 ? 'amarillo' : 'verde',
  inventario: diasInv === null ? 'gris' : diasInv < 7 ? 'rojo' : (N(invK.negativos) > 20 || diasInv > 90) ? 'amarillo' : 'verde',
};
// ---- atención ----
const $$ = n => (Number(n) < 0 ? '-$' : '$') + Math.round(Math.abs(Number(n || 0))).toLocaleString('es-MX');
const X = [];
for (const x of (r.revisar || [])) X.push([1, 'rojo', `Corregir ${x.tipo === 'P' ? 'pedido' : x.tipo === 'R' ? 'remisión' : 'factura'} ${x.folio} · ${$$(x.total)}`]);
if (N(tin.n)) { const v0 = (tin.lista || [])[0] || {};
  X.push([1, 'rojo', `${tin.n} pedido(s) de tinacos con más de ${tin.lim} días sin surtir (${$$(tin.t)}) · el más viejo ${v0.folio || ''}${v0.cliente ? ' · ' + v0.cliente : ''} (${v0.dias} días)`]); }
if (difCaja !== null && Math.abs(difCaja) > TOL2) X.push([2, 'rojo', `Caja con ${difCaja < 0 ? 'faltante' : 'sobrante'} de $${Math.abs(difCaja).toFixed(2)}`]);
const va = k.validacion || {};
for (const x of (va.pv_y_rem || [])) X.push([3, 'amarillo', `Posible doble captura: ticket ${x.ticket} y remisión ${x.remision} (${$$(x.total)})`]);
for (const x of (va.rem_dobles || [])) X.push([3, 'amarillo', `Remisiones ${x.f1} y ${x.f2} iguales (${$$(x.total)})`]);
for (const x of (va.pv_dobles || [])) X.push([3, 'amarillo', `Tickets ${x.f1} y ${x.f2} iguales (${$$(x.total)})`]);
if (avance !== null && avance < 0.85) X.push([4, 'rojo', `Venta ${Math.round((1 - avance) * 100)}% abajo de ${metaDia ? 'la meta' : 'tu promedio'}`]);
const pa = (k.pend || {}).ped_atorado;
if (pa) X.push([5, pa.dias > 10 ? 'rojo' : 'amarillo', `${pa.folio} · ${pa.dias} días sin surtir${pa.cliente ? ' · ' + pa.cliente : ''}`]);
if (!cierre && fondos.length) X.push([6, 'amarillo', 'La caja no hizo su cierre']);
if (difCaja !== null && Math.abs(difCaja) > TOL1 && Math.abs(difCaja) <= TOL2) X.push([6, 'amarillo', `Caja ${difCaja < 0 ? 'faltante' : 'sobrante'} $${Math.abs(difCaja).toFixed(2)}`]);
if (diasInv !== null && diasInv < 7) X.push([6, 'rojo', `Inventario solo para ~${diasInv} días`]);
if (u.venta_siva && cob < 0.9) X.push([7, 'amarillo', `${Math.round((1 - cob) * 100)}% de la venta de hoy sin costo en Microsip (usa /margen en Telegram)`]);
if (N(invK.negativos) > 20) X.push([8, 'amarillo', `${invK.negativos} artículos con existencia negativa`]);
if (N(pe.hist)) X.push([7, 'amarillo', `Depurar ${pe.hist} pedidos históricos (+30 días)`]);
const ra = (k.pend || {}).rem_atorada;
if (ra) X.push([8, 'amarillo', `Remisión ${ra.folio} · ${ra.dias} días sin facturar`]);
if (credM > cobM && credM > 0) X.push([9, 'amarillo', 'Este mes se da más crédito del que se cobra']);
X.sort((a, b) => a[0] - b[0]);
// ---- punto de venta y movimientos de caja ----
const pvR = r.pv || [];
const tPV = pvR.reduce((s, x) => s + N(x.t), 0), nPV = pvR.reduce((s, x) => s + N(x.n), 0);
const listaR = r.movs_lista || [];
// ---- cemento (mismo cálculo que el reporte diario) ----
let cemento = null;
if (cem.hoy) {
  const meta = N(cem.meta) || N(cfg.meta_ton) || 200, hoyC = String(cem.hoy).slice(0, 10), kgB = N(cfg.kg_por_bulto) || 50;
  const meses = cem.meses || [];
  const act = meses.find(x => String(x.mes).slice(0, 7) === hoyC.slice(0, 7)) || {};
  const tonAct = N(act.ton_meta);
  const proy = cem.dias_hab_transc > 0 ? tonAct / cem.dias_hab_transc * cem.dias_hab_mes : null;
  const faltanDias = Math.max(1, N(cem.dias_hab_mes || 26) - N(cem.dias_hab_transc));
  const porDia = Math.max(0, meta - tonAct) / faltanDias;
  const dias = (cem.dias || []).map(x => ({ fecha: String(x.fecha).slice(0, 10), ton: N(x.ton), publico: N(x.publico), reventa: N(x.reventa), b50: N(x.bultos50), b25: N(x.bultos25) }));
  const d0 = dias.find(x => x.fecha === hoyC) || { ton: 0, publico: 0, reventa: 0, b50: 0, b25: 0 };
  const ult = dias.filter(x => x.fecha < hoyC).slice(-20);
  const prom20 = ult.length ? ult.reduce((a, x) => a + x.ton, 0) / ult.length : null;
  const dow = ((new Date(hoyC + 'T12:00:00Z').getUTCDay() + 6) % 7) + 1;
  const ds = (cem.dias_semana || []).find(x => x.n === dow) || {};
  const llamar = (cem.clientes || []).filter(c => c.le_toca).sort((a, b) => N(b.ton_mes_ref || b.ton_mes_ult3) - N(a.ton_mes_ref || a.ton_mes_ult3))
    .slice(0, 8).map(c => ({ cliente: c.cliente, dias: c.dias_sin_comprar, tel: c.telefono1 || '', ton_mes: N(c.ton_mes_ref || c.ton_mes_ult3) }));
  cemento = { hoy: hoyC, meta, kg: kgB, dia: d0, prom_dia_semana: N(ds.ton_por_dia), dia_semana: ds.dia || '', prom20, mes_ton: tonAct, proy, por_dia: porDia,
    bultos_dia: Math.round(porDia * 1000 / kgB), faltan_dias: faltanDias, serie: dias.filter(x => x.fecha.slice(0, 7) === hoyC.slice(0, 7) || x.fecha > hoyC.slice(0, 8) + '00').slice(-31),
    meses: meses.slice(-6).map(x => ({ mes: String(x.mes).slice(0, 7), ton: N(x.ton_meta) })), llamar };
}
const respuesta = {
  ok: true, fecha: r.fecha, ultima_copia: r.ultima_copia || '', minutos_desde_copia: r.minutos_desde_copia ?? null, semaforo,
  ventas: { hoy: hoyV, meta_dia: metaDia, prom30: prom, vs: metaDia ? pct(hoyV, metaDia) : pct(hoyV, prom), contra: metaDia ? 'meta' : 'promedio 30 días',
    ayer: k.ayer || null, sem_pasada: N(k.sem_pasada), mes: N(m.venta), meta_mes: META, proy: m.venta && m.hab_transcurridos ? N(m.venta) / m.hab_transcurridos * m.hab_totales : null,
    hab_transcurridos: m.hab_transcurridos, hab_totales: m.hab_totales, semanas: m.semanas || [], semana: k.semana || null },
  utilidad: { hoy: utilHoy, margen, cobertura: cob, provisional: !!u.venta_siva && cob < 0.95, mes: utilMes, margen_mes: m.venta_con_costo ? utilMes / N(m.venta_con_costo) : null },
  cobranza: { hoy: cobranzaHoy, credito_hoy: creditoHoy, creditos: r.creditos || [], mes: cobM, credito_mes: credM, gastos_mes: N(m.gastos_caja) },
  caja: { esperado, fondo: fondoIni, entrego: cierre ? N(cierre.efectivo) : null, caja: cierre ? cierre.caja : '', hora: cierre ? cierre.hora : '', dif: difCaja,
    sin_cierre: !cierre && fondos.length > 0, tol: TOL1, cortes: r.cortes || [] },
  pv: { total: tPV, tickets: nPV, por_caja: r.pv_caja || [], formas: de('V').map(x => ({ forma: x.forma, t: N(x.t), credito: !!x.credito, efectivo: !!x.efectivo })) },
  movimientos: { ingresos: listaR.filter(x => x.tdoc === 'I'), retiros: listaR.filter(x => x.tdoc === 'R').sort((a, b) => N(b.t) - N(a.t)), cobros: listaR.filter(x => x.tdoc === 'P'),
    devoluciones: suma(de('D')), t_ingresos: suma(de('I')), t_retiros: suma(de('R')) },
  pedidos: { nuevos: ped, salidas: rem, facturas: r.facturas || {}, pendientes: totPend, buckets: pe, rem_buckets: pr, ped_pend: r.ped_pend || {}, rem_pend: r.rem_pend || {},
    tinacos: { n: N(tin.n), t: N(tin.t), lim: N(tin.lim) || 5, lista: tin.lista || [] },
    atorado: pa || null, rem_atorada: ra || null, cancelados: r.cancelados || [] },
  inventario: { valor: N(invK.valor), dias: diasInv, negativos: N(invK.negativos), ocultar_neg: $('Panel · Configuración').first().json.ocultar_existencia_negativa === true, almacenes: r.inventario || [] },
  lineas: { peores: k.lineas || [], hoy: k.lineas_hoy || [] }, clientes: k.clientes || {},
  atencion: X.map(x => ({ nivel: x[1], texto: x[2] })), cemento,
};
return [{ json: { respuesta } }];

const __leer = () => {
const cfg = $('Panel · Config consultas').first().json;
const u = cfg.body || {};
const VIA = cfg.via;
if (VIA === 'choferes' && u.callback_query) {
  // Botones del grupo del quemador: "Ya la preparé" y "Pendientes"
  const q = u.callback_query, d = String(q.data || '');
  const ch = String((q.message && q.message.chat && q.message.chat.id) || '');
  const QUEM = String(cfg.chat_id_quemador || '').trim();
  // Botones de entrega en el grupo de choferes
  const CHOFC = String(cfg.chat_id_choferes || '').trim();
  const privadoCb = q.message && q.message.chat && q.message.chat.type === 'private';
  if (((CHOFC && ch === CHOFC) || privadoCb) && /^(ent|noent|mot)\|/.test(d)) {
    const [op, folio, motivo] = d.split('|');
    return [{ json: { ruta: 'entrega', op, folio: folio || '', motivo: motivo || '', cb_id: q.id, chat_origen: ch,
      message_id: q.message.message_id, markup: q.message.reply_markup || null, texto_msg: q.message.text || '',
      quien: [q.from && q.from.first_name, q.from && q.from.last_name].filter(Boolean).join(' ') } }];
  }
  if (!QUEM || ch !== QUEM || !/^prepl?\|/.test(d)) return [];
  const quien = [q.from && q.from.first_name, q.from && q.from.last_name].filter(Boolean).join(' ');
  const [tag, oid, org] = d.split('|');
  return [{ json: { ruta: 'preparar', op: tag === 'prep' ? 'marcar' : 'lista', order_id: oid || '', desde_lista: org === 'l',
    cb_id: q.id, chat_origen: ch, message_id: q.message.message_id, quien } }];
}
const CHAT = String(cfg.chat_id);
const AYUDA = `<b>Comandos de inventario ML</b>
<code>/inventario</code> – stock de todas tus publicaciones
<code>/inventario cisterna</code> – solo las que coincidan
<code>/stock 1100 slim beige 10</code> – deja ese color en 10 piezas (0 = ya no hay)
<code>/pausar cisterna 2800</code> – pausa la publicación
<code>/activar cisterna 2800</code> – la vuelve a activar
Antes de cambiar algo te pido confirmación con botones.

<b>Ventas (Microsip)</b>
<code>/ultima</code> – última venta de cada caja
<code>/ultima pedregal</code> – última venta de esa caja o sucursal
<code>/hoy</code> – cómo va el día (PV, cobros de crédito, pedidos, remisiones, facturas)
<code>/corte</code> – datos del corte de caja de hoy (revisión)
<code>/avance</code> – cómo vamos contra la meta del mes y la semana
<code>ubicación Diana</code> – ubicación del pedido (por nombre o folio)
<code>teléfono Diana</code> – teléfono y dirección del cliente en Microsip
<code>existencia tinaco 1100</code> – cuánto hay de un artículo (por nombre o clave)
<code>seguimiento P3972</code> – estatus de un pedido, sus remisiones, qué se surtió y qué falta
<code>ruta walas</code> o <code>ruta martin mañana</code> – ruta de un chofer
<code>por preparar</code> – ventas de Mercado Envíos que el quemador no ha marcado como preparadas
<code>últimos pedidos</code> – los 3 pedidos más recientes (o <code>últimos 5 pedidos</code>)

<b>Detalle del día</b> (también escribiéndolo normal, ej. "cobros de hoy")
/cobros · /credito · /pedidos · /pendientes (o "pedidos +30") · /remisiones · /gastos · /caja · /lineas · /mes
<code>/margen</code> – revisar costo y margen por artículo
<code>/costo CLAVE 950</code> – fijar a mano el costo de un artículo
<code>/meta 1600000</code> – poner meta del mes (también <code>/meta semanal 400000</code>)
<code>/cajas</code> – revisión técnica de datos de caja`;
if (u.callback_query) {
  const q = u.callback_query;
  const chat = String((q.message && q.message.chat && q.message.chat.id) || '');
  if (chat !== CHAT) return [];
  // Botones del aviso "Clientes sin respuesta": sr|a|id (ya lo atendí), sr|n|id (no le interesa), sr|x|id (ya marcado)
  if (String(q.data || '').startsWith('sr|')) {
    const [, op, id] = String(q.data).split('|');
    const quien = [q.from && q.from.first_name, q.from && q.from.last_name].filter(Boolean).join(' ');
    if (op === 'x') return [{ json: { ruta: 'texto', metodo: 'answerCallbackQuery', cuerpo: { callback_query_id: q.id, text: 'Ese chat ya estaba marcado' } } }];
    return [{ json: { ruta: 'sin_resp', op, id: id || '', estado: op === 'n' ? 'no_interesado' : 'atendido', cb_id: q.id, chat_origen: chat,
      message_id: q.message.message_id, markup: q.message.reply_markup || null, quien } }];
  }
  if (String(q.data || '').startsWith('q|')) {
    return [{ json: { ruta: 'microsip', accion: String(q.data).split('|')[1], consulta: '', cb_id: q.id,
      reply: { message_id: q.message.message_id, allow_sending_without_reply: true } } }];
  }
  const [accion, item, variacion, cantidad] = String(q.data || '').split('|');
  return [{ json: { ruta: 'boton', cb_id: q.id, chat_id: chat, message_id: q.message.message_id,
    accion, item: item || '', variacion: variacion || '0', cantidad: Number(cantidad),
    quien: [q.from && q.from.first_name, q.from && q.from.last_name].filter(Boolean).join(' ') } }];
}
const nombreChofer = n => {
  const CH = { walas: 'WALAS', wallace: 'WALAS', walace: 'WALAS', martin: 'MARTIN', marin: 'MARTIN', sauso: 'SAUSO' };
  const w = (n.match(/\b(wal\w*|mar\w*|mra\w*|sau\w*)\b/) || [])[1] || '';
  return CH[w] || (/^wal/.test(w) ? 'WALAS' : /^(mar|mra)/.test(w) ? 'MARTIN' : /^sau/.test(w) ? 'SAUSO' : '');
};
const pedirRuta = (txt, chat, rep) => {
  const n = txt.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const CH = { walas: 'WALAS', wallace: 'WALAS', walace: 'WALAS', martin: 'MARTIN', marin: 'MARTIN', sauso: 'SAUSO' };
  const w = (n.match(/\b(wal\w*|mar\w*|mra\w*|sau\w*)\b/) || [])[1] || '';
  const dia = /manana/.test(n) ? 'mañana' : ((n.match(/\d{1,2}\/\d{1,2}/) || [])[0] || 'hoy');
  const nom = CH[w] || (/^wal/.test(w) ? 'WALAS' : /^(mar|mra)/.test(w) ? 'MARTIN' : /^sau/.test(w) ? 'SAUSO' : '');
  return [{ json: { ruta: 'pedir_ruta', chofer: nom, dia, chat_id: String(chat), reply: rep } }];
};
const m = u.message || u.edited_message;
if (!m || (!m.text && !m.location)) return [];
const ORIGEN = String(m.chat.id);
const CHOF = String(cfg.chat_id_choferes || '').trim();
