const hace = m => { m = Number(m || 0); if (m < 1) return 'menos de 1 min'; if (m < 60) return `${m} min`;
  if (m < 1440) return `${Math.floor(m / 60)} h ${m % 60} min`; return `${Math.floor(m / 1440)} días`; };
const enviar = text => ({ json: { metodo: 'sendMessage', cuerpo: { chat_id: CHAT, text, parse_mode: 'HTML', reply_parameters: p.reply } } });
const partir = L => { const out = []; let c = ''; for (const l of L) { if ((c + l).length > 3800) { out.push(c); c = ''; } c += l + '\n'; } if (c) out.push(c); return out; };
const errQ = $input.first().json.error;
if (errQ) { const eTxt = typeof errQ === 'string' ? errQ : [errQ.message, errQ.description, errQ.context && JSON.stringify(errQ.context)].filter(Boolean).join(' | ') || JSON.stringify(errQ);
  return [enviar('⚠️ No pude hacer la consulta (' + esc(p.accion) + '). Mándale este texto a Claude:\n<code>' + esc(String(eTxt).slice(0, 700)) + '</code>')]; }
if (p.accion === 'ultima') {
  const f = r.filas || [];
  if (!f.length) return [enviar(`No encontré ventas de caja${p.consulta ? ' para <b>' + esc(p.consulta) + '</b>' : ''} en los últimos 7 días.`)];
  const L = [`<b>🧾 Última venta${f.length > 1 ? ' por caja' : ''}</b>`];
  for (const x of f) {
    L.push(`\n<b>${esc(x.caja)}</b>${x.almacen && x.almacen !== x.caja ? ' · ' + esc(x.almacen) : ''}\n` +
      `Hace <b>${hace(x.minutos)}</b> (${esc(x.hora)}${x.es_hoy ? '' : ' del ' + esc(x.fecha)}) · Ticket ${esc(x.folio)} · <b>${$$(x.total)}</b>` +
      (x.cajero ? ` · ${esc(x.cajero)}` : '') +
      (x.articulos ? `\n<i>${esc(String(x.articulos).slice(0, 160))}</i>` : ''));
  }
