  L.push(`<b>📊 Avance de ${mesN}</b> <i>(corte ${esc(r.fecha)} ${esc(r.copia || '')})</i>`);
  L.push(`Vendido en el mes: <b>${$c(vm)}</b>`);
  if (mm) {
    L.push(`Meta del mes: ${$c(mm)} · avance <b>${Math.round(vm / mm * 100)}%</b>`);
    if (md) L.push(`🎯 Meta diaria normal: ${$c(md)}`);
    // Lo que falta se reparte entre los días hábiles que quedan (incluye hoy si el día sigue en curso)
    const dias = Number(r.hab_rest || 0) + (diaEnCurso ? 1 : 0);
    const falta = mm - (diaEnCurso ? vm - vh : vm);
    if (vm >= mm) L.push('🎉 ¡Meta del mes alcanzada!');
    else if (dias > 0) L.push(`🏁 Necesario para alcanzar la meta: <b>${$c(falta / dias)}/día</b> · ${dias} días hábiles`);
    else L.push(`Faltaron ${$c(mm - vm)} para la meta.`);
    if (Number(r.hab_trans)) {
      const proy = vm / Number(r.hab_trans) * Number(r.hab_tot);
      const g = Math.round((proy / mm - 1) * 100);
      L.push(`🔮 Al ritmo actual cierras en ${$c(proy)} (${g >= 0 ? '+' : ''}${g}% vs meta)`);
    }
  } else {
    L.push('Todavía no hay meta del mes. Ponla con <code>/meta 1600000</code>');
  }
  const ms = Number(r.meta_sem || 0) || (mm && Number(r.hab_tot) ? mm / Number(r.hab_tot) * Number(r.hab_sem || 6) : 0);
  if (ms) {
    const vs = Number(r.venta_sem || 0);
    L.push(`\nSemana (desde ${esc(r.ini_sem)}): <b>${$c(vs)}</b> de ${$c(ms)} · ${Math.round(vs / ms * 100)}%` + (vs >= ms ? ' ✅' : ''));
  }
  // Hoy: el semáforo toma en cuenta la hora (antes de las 2 pm no se marca en rojo)
  let semH = '';
  if (md) {
    const ph = vh / md;
    semH = ph >= 1 ? ' ✅' : (diaEnCurso && hora < 14) ? ' ⏳ en curso' : ph >= 0.7 ? ' 🟡' : ' 🔴';
  }
  L.push(`Hoy: <b>${$c(vh)}</b>` + (md ? ` · ${Math.round(vh / md * 100)}% de meta` : '') + ` · corte ${esc(r.copia || '')}${semH}`);
  const li = r.lineas || [];
  const MESANT = MESES[((Number(r.mes_nombre) || 1) + 10) % 12].toLowerCase();
  if (li.length) {
    L.push(`\n<b>Líneas del mes</b> <i>(% del mes${r.hist_mes_ant ? ' · vs mismos días de ' + MESANT : ''})</i>`);
    for (const x of li) {
      const t = Number(x.t), ant = Number(x.ant || 0);
      const part = Number(r.lineas_total) ? (t / Number(r.lineas_total) * 100).toFixed(1) + '%' : '';
      let comp = '';
      if (r.hist_mes_ant) {
        if (ant <= 0) comp = ' · nuevo';
        else if (ant < 2000 || t / ant > 3) comp = ' · ↑ base baja';
        else { const v = Math.round((t / ant - 1) * 100); comp = ` · ${v >= 0 ? '↑' : '↓'} ${Math.abs(v)}%`; }
      }
      L.push(`   ${esc(x.linea)}: ${$c(t)} · ${part}${comp}`);
    }
  }
  return partir(L).map(enviar);
}

if (p.accion === 'margen') {
  const f = r.filas || [];
  const L = ['<b>🔎 Margen por artículo (mes)</b> <i>sin IVA · costo: manual › última compra › promedio de Microsip</i>'];
  for (const x of f) {
    const m = x.margen === null ? null : Number(x.margen);
    const ic = m === null ? '⚪' : (m < 0 || m > 60) ? '⚠️' : '✅';
    L.push(`${ic} ${esc(String(x.articulo || '').slice(0, 34))} <code>${esc(x.clave || '')}</code>\n   vendió ${$$(x.venta)} · precio prom ${$$(x.precio_prom)} · costo ${x.costo_prom === null ? 'sin costo' : $$(x.costo_prom) + ' (' + esc(x.fuente) + ')'} · margen ${m === null ? '¿?' : m + '%'}`);
  }
  L.push('\n⚠️ = margen negativo o arriba de 60%: revisar costo o unidad en Microsip.\nPara fijar un costo a mano (por ejemplo tus tinacos): <code>/costo CLAVE 950</code> o <code>/costo tinaco slim 1100 beige 950</code>');
  return partir(L).map(enviar);
}
if (p.accion === 'costo') {
  if (r.guardado) {
    const x = r.pick || {};
    const pl = Number(x.precio_lista || 0), c = Number(r.costo || 0);
    return [enviar(`✅ Costo guardado: <b>${esc(x.nombre)}</b> <code>${esc(x.clave || '')}</code> = <b>${$$(c)}</b> (sin IVA)` +
      (pl ? `\nPrecio de lista ${$$(pl)} → margen ${Math.round((1 - c / pl) * 100)}%` : '') +
      `\nSe usará en la utilidad del resumen y en /margen. Para quitarlo, pon otro costo.`)];
  }
  if (!Number(r.n)) return [enviar(`No encontré artículos con <b>${esc(String(p.consulta).split('|')[0])}</b>. Usa la clave (sale en /margen) o menos palabras.`)];
  return [enviar(`Encontré ${r.n} artículos. Usa la clave exacta:\n` + (r.cand || []).map(x => `<code>/costo ${esc(x.clave)} ${Number(r.costo) || 'MONTO'}</code> · ${esc(x.nombre)}`).join('\n'))];
}
if (p.accion === 'corte') {
  const L = ['<b>🔎 Datos del corte de hoy</b> (reenvíale esto a Claude junto con el monto que entregó la caja)'];
  for (const k of ['movtos', 'fondo', 'docs', 'cobros_tipo', 'efvo'])
    L.push(`\n<b>${k}</b>\n<pre>${esc(JSON.stringify(r[k] || []).slice(0, 1800))}</pre>`);
  return partir(L).map(enviar);
}
return [];

// Busca el pedido en la hoja "pedidos" por folio o nombre y manda la ubicación
const cfg = $('Panel · Config consultas').first().json;
const p = $('Panel · Leer comando').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && (f.folio || f.cliente));
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const q = norm(p.consulta);
const enviar = (metodo, cuerpo) => ({ json: { metodo, cuerpo: Object.assign({ chat_id: String(p.chat_origen || cfg.chat_id) }, cuerpo) } });
const texto = t => enviar('sendMessage', { text: t, parse_mode: 'HTML', disable_web_page_preview: true, reply_parameters: p.reply });
if (!q) return [texto('Escribe así: <code>ubicación Diana</code> o <code>ubicación ML-2000018648237776</code> (también sirve el folio o las últimas cifras).')];
const toks = q.split(/\s+/).filter(Boolean);
const cerrados = /entregad|cancelad/;
let m = filas.map((f, i) => ({ f, i })).filter(({ f }) => {
  const folio = norm(f.folio), fm = norm(f.folio_microsip), cli = norm(f.cliente), qq = q.replace(/\s/g, '');
  return (folio && (folio === q || folio.endsWith(qq))) || (fm && (fm === qq || fm.endsWith(qq))) || toks.every(t => cli.includes(t));
});
const abiertos = m.filter(({ f }) => !cerrados.test(norm(f.estado)));
if (abiertos.length) m = abiertos;
m = m.sort((a, b) => b.i - a.i).slice(0, 4);
if (!m.length) return [texto(`No encontré pedidos de <b>${esc(p.consulta)}</b> en la hoja. Prueba con otro nombre o con el folio.`)];
const out = [];
for (const { f } of m) {
  const dir = [f.direccion, f.colonia, f.cp ? 'CP ' + f.cp : ''].filter(Boolean).join(', ');
  const real = String(f.ubicacion_cliente || '').match(/https?:\/\/\S+/);
  const L = [`<b>📦 ${esc(f.cliente || 'Sin nombre')}</b> · ${esc(f.folio || '')}${f.folio_microsip ? ' · Microsip ' + esc(f.folio_microsip) : ''}`];
  if (f.producto) L.push(`${esc(f.producto)}${f.color ? ' ' + esc(f.color) : ''}${f.cantidad ? ' x' + esc(f.cantidad) : ''}`);
  if (dir) L.push(`🏠 ${esc(dir)}`);
  if (f.telefono) L.push(`📞 ${esc(f.telefono)}`);
  if (f.estado || f.fecha_entrega || f.chofer) L.push(`Estado: ${esc(f.estado || '¿?')}${f.fecha_entrega ? ' · entrega ' + esc(f.fecha_entrega) : ''}${f.chofer ? ' · chofer ' + esc(f.chofer) : ''}`);
  if (real) {
    L.push(`\n✅ <b>Ubicación que mandó el cliente:</b>\n${esc(real[0])}`);
  } else if (dir) {
    L.push(`\n⚠️ <b>Ubicación aproximada</b> (generada con la dirección, puede variar; confirma con el cliente):\nhttps://www.google.com/maps/search/?api=1&query=${encodeURIComponent(dir + ', México')}`);
  } else L.push('\n❌ Sin dirección ni ubicación todavía.');
  out.push(texto(L.join('\n')));
  // Si la ubicación del cliente trae coordenadas, se manda también el pin de Telegram
  const c = real && decodeURIComponent(real[0]).match(/(-?\d{1,2}\.\d{3,})\s*,\s*(-?\d{1,3}\.\d{3,})/);
  if (c) out.push(enviar('sendLocation', { latitude: Number(c[1]), longitude: Number(c[2]) }));
}
if (m.length > 1) out.unshift(texto(`Encontré ${m.length} pedidos, te mando los más recientes:`));
return out;

// Respuestas del bot de preparación (grupo del quemador)
const p = $('Panel · Leer comando').first().json;
const r = $input.first().json.r || {};
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hora = new Date(Date.now() - 6 * 3600000).toISOString().slice(11, 16);
const out = [];
const send = (metodo, cuerpo) => out.push({ json: { metodo, cuerpo } });
const lista = () => {
  const P = r.pend || [];
  if (!P.length) return { text: '✅ <b>Todo preparado.</b> No hay ventas pendientes por armar.', kb: [] };
  const L = [`📋 <b>Pendientes por preparar (${P.length})</b>`, ''];
  const DIAS = ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'];
  const plazo = x => {
    if (!x.limite) return '';
    const lim = String(x.limite).slice(0, 10), dd = Number(x.dias);
    const dt = new Date(lim + 'T12:00:00Z'), dm = `${DIAS[dt.getUTCDay()]} ${lim.slice(8, 10)}/${lim.slice(5, 7)}`;
    const hora = x.limite_hora ? ` antes de las ${esc(x.limite_hora)}` : '';
    if (dd < 0) return `\n   ⚠️ <b>ATRASADA</b> (debía salir el ${dm}): mandar HOY`;
    return `\n   ⏰ ${esc(x.limite_accion || 'Enviar')}: <b>${dd === 0 ? 'HOY' + hora : dd === 1 ? 'MAÑANA ' + dm + hora : dm + hora}</b>`;
  };
  P.slice(0, 20).forEach((x, i) => L.push(`${i + 1}. <b>${esc(x.titulo || x.folio)}</b>${x.variante ? ' · ' + esc(x.variante) : ''} · x${x.cantidad || 1}\n   ${esc(x.folio)} · desde ${esc(x.cuando)}${plazo(x)}`));
  L.push('', '<i>Ordenadas de la más urgente a la menos urgente.</i>');
  if (P.length > 20) L.push(`… y ${P.length - 20} más.`);
  const kb = p.sin_botones ? [] : P.slice(0, 10).map((x, i) => [{ text: `✅ ${i + 1}. ${String(x.titulo || x.folio).slice(0, 30)}`, callback_data: `prep|${x.order_id}|l` }]);
  return { text: L.join('\n'), kb };
};
const reLista = () => { const l = lista(); send('editMessageText', { chat_id: String(p.chat_origen), message_id: Number(p.message_id), parse_mode: 'HTML', text: l.text, reply_markup: { inline_keyboard: l.kb } }); };
if (p.op === 'marcar') {
  const mk = r.marcado, pv = r.previo;
  if (mk) {
    send('answerCallbackQuery', { callback_query_id: p.cb_id, text: '✅ Marcada como preparada' });
    const cid = p.desde_lista ? mk.chat_id : p.chat_origen, mid = p.desde_lista ? mk.message_id : p.message_id;
    if (mid) send('editMessageText', { chat_id: String(cid), message_id: Number(mid), parse_mode: 'HTML',
      text: `${mk.texto || ''}\n\n✅ <b>Preparada</b> por ${esc(p.quien || '')} · ${hora}` });
    if (p.desde_lista) reLista();
  } else if (pv) {
    send('answerCallbackQuery', { callback_query_id: p.cb_id, show_alert: true,
      text: pv.cancelado ? '❌ Esta venta se canceló: NO prepararla' : `Ya estaba preparada por ${pv.por || 'alguien'} (${pv.hora})` });
    if (p.desde_lista) reLista();
    else send('editMessageReplyMarkup', { chat_id: String(p.chat_origen), message_id: Number(p.message_id), reply_markup: { inline_keyboard: [] } });
  } else send('answerCallbackQuery', { callback_query_id: p.cb_id, text: 'No encontré esta venta en el registro' });
} else {
  if (p.cb_id) send('answerCallbackQuery', { callback_query_id: p.cb_id, text: '📋 Pendientes' });
  const l = lista();
  send('sendMessage', { chat_id: String(p.chat_origen), parse_mode: 'HTML', text: l.text, reply_markup: { inline_keyboard: l.kb } });
}
return out;

// Junta lo que el bot habría mandado a Telegram y lo regresa a la página
const cfg = $('Panel · Config consultas').first().json;
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.ruta === 'pedir_ruta') {
    const u = String(cfg.url_choferes || '').trim();
    out.push(`🚚 <b>Ruta de ${j.chofer || 'chofer'}</b> (${j.dia || 'hoy'})\n` + (u ? `Ábrela en la página de choferes: ${u}` : 'Pega la liga de oficina de la página de choferes en el nodo "Config consultas" (url_choferes) para abrirla desde aquí.'));
    continue;
  }
  const c = j.cuerpo || {};
  if (c.text) out.push(String(c.text));
  else if (c.caption) out.push(String(c.caption));
  else if (c.latitude != null) out.push(`📍 https://www.google.com/maps?q=${c.latitude},${c.longitude}`);
}
return [{ json: { respuesta: { ok: true, mensajes: out } } }];

// Proveedores (lo que se debe, de Pagos a proveedores) y flujo de efectivo a 8 semanas
function planPagos(arr, abono, hoy, semanas, abonadoSemana) {
  const dmas = (iso, n) => { const d = new Date(iso + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
  const dow = new Date(hoy + 'T12:00:00Z').getUTCDay(), lunes = dmas(hoy, -((dow + 6) % 7));
  const W = [];
  for (let i = 0; i < (semanas || 8); i++) W.push({ ini: i ? dmas(lunes, 7 * i) : hoy, fin: dmas(lunes, 7 * i + 6), total_vence: 0, total_abono: 0 });
  const saldo = x => Math.max(0, Number(x.monto) - Number(x.pagado || 0));
  const venc = arr.filter(x => saldo(x) > 0.5 && x.vence < hoy).sort((a, b) => (a.vence < b.vence ? -1 : a.vence > b.vence ? 1 : 0)).map(x => ({ ...x, resta: saldo(x) }));
  for (const x of arr.filter(x => saldo(x) > 0.5 && x.vence >= hoy)) { const w = W.find(w => x.vence <= w.fin); if (w) w.total_vence += saldo(x); }
  let k = 0; const A = Math.max(0, Number(abono) || 0);
  for (const w of W) {
    let bolsa = w === W[0] ? Math.max(0, A - (Number(abonadoSemana) || 0)) : A;
    while (bolsa > 0.5 && k < venc.length) { const x = venc[k], m = Math.min(bolsa, x.resta); w.total_abono += m; x.resta -= m; bolsa -= m; if (x.resta <= 0.5) k++; }
  }
  return { semanas: W, vencido: venc.reduce((s, x) => s + saldo(x), 0) };
}
const N = v => Number(v || 0);
let D = null; try { D = $('Panel · Lo que se debe (panel)').first().json.r; if (typeof D === 'string') D = JSON.parse(D); } catch (e) { D = null; }
if (!D || !D.ok) return [{ json: { respuesta: { ok: true, prov: null, msg: 'No se pudo leer lo que se debe a proveedores. Revisa que el flujo «Pagos a proveedores» esté instalado y que Microsip ya se haya copiado.' } } }];
let G = {}; try { G = $('Panel · Gastos para el flujo').first().json.g || {}; if (typeof G === 'string') G = JSON.parse(G); } catch (e) { G = {}; }
const hoy = D.hoy, saldo = x => Math.max(0, N(x.monto) - N(x.pagado));
const its = (D.items || []).filter(x => saldo(x) > 0.5);
const por = {};
for (const x of its) { const g = por[x.nombre] = por[x.nombre] || { nombre: x.nombre, saldo: 0, vencido: 0, proximo: null, notas: 0 }; g.saldo += saldo(x); g.notas++; if (x.vence < hoy) g.vencido += saldo(x); else if (!g.proximo || x.vence < g.proximo) g.proximo = x.vence; }
const lista = Object.values(por).sort((a, b) => b.saldo - a.saldo);
const plan = planPagos(its, D.abono, hoy, 8, D.abonado_semana);
const dmas = (iso, n) => { const d = new Date(iso + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const total = its.reduce((s, x) => s + saldo(x), 0);
const vence7 = its.filter(x => x.vence >= hoy && x.vence <= dmas(hoy, 7)).reduce((s, x) => s + saldo(x), 0);
// ventas: promedio de las últimas 4 semanas cerradas
const fl = (D.flujo || []);
const cerradas = fl.slice(0, -1).slice(-4);
const ventaSem = cerradas.length ? cerradas.reduce((s, x) => s + N(x.ventas), 0) / cerradas.length : 0;
const semanas = plan.semanas.map((w, i) => ({
  ini: w.ini, proveedores: Math.round(w.total_vence + w.total_abono), vence: Math.round(w.total_vence), abono: Math.round(w.total_abono),
  nomina: Math.round(N(G.nomina_sem)), otros: Math.round(N(G.otros_sem))
}));
// antigüedad de lo que se debe: días pasados de la fecha de vencimiento de cada nota
const dd = (a, b) => Math.round((Date.parse(a + 'T12:00:00Z') - Date.parse(b + 'T12:00:00Z')) / 86400000);
const antig = { por_vencer: 0, v1_30: 0, v31_60: 0, v60: 0 };
for (const x of its) { const d = dd(hoy, x.vence), s = saldo(x); if (d <= 0) antig.por_vencer += s; else if (d <= 30) antig.v1_30 += s; else if (d <= 60) antig.v31_60 += s; else antig.v60 += s; }
for (const k of Object.keys(antig)) antig[k] = Math.round(antig[k]);
return [{ json: { respuesta: { ok: true, prov: {
  hoy, total: Math.round(total), vencido: Math.round(plan.vencido), vence7: Math.round(vence7), abono: N(D.abono), abonado_semana: N(D.abonado_semana),
  proveedores: lista.map(g => ({ ...g, saldo: Math.round(g.saldo), vencido: Math.round(g.vencido) })), notas: its.length,
  sin_ms: its.filter(x => x.sin_ms).length, antig
}, flujo: { venta_sem: Math.round(ventaSem), semanas, base_gastos: N(G.semanas_con_datos), ventas_hist: cerradas.map(x => ({ ini: x.ini, ventas: N(x.ventas), compras: N(x.compras) })) } } } }];

// Indicadores del mes para el panel (los cálculos de rotación, días, GMROI y bono se hacen en la página)
let r = null;
for (const it of $input.all()) { let v = it.json.r; if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { v = null; } } if (v && v.mes) r = v; }
if (!r) return [{ json: { respuesta: { ok: false, msg: 'No se pudieron calcular los indicadores del mes.' } } }];
// meses pasados: saldo de clientes al cierre calculado en Microsip (si ya existe)
const h = r.cxc_hist;
if (h && r.cxc && h.saldo != null) {
  Object.assign(r.cxc, { saldo_hoy: r.cxc.saldo, saldo: Number(h.saldo || 0), por_vencer: Number(h.b0 || 0), v1_30: Number(h.b1 || 0),
    v31_60: Number(h.b2 || 0), v60: Number(h.b3 || 0), fuente: 'cierre', corte: h.corte || r.fin_mes, n_clientes: h.n });
}
return [{ json: { respuesta: { ok: true, ind: r } } }];

parameters.query:
CREATE TABLE IF NOT EXISTS tablero_metas (mes DATE NOT NULL, base TEXT NOT NULL, clave TEXT NOT NULL, valor NUMERIC, por TEXT, actualizado TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (mes, base, clave));
CREATE TABLE IF NOT EXISTS tablero_config (clave TEXT PRIMARY KEY, valor TEXT, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vendedor_seguimientos (id BIGSERIAL PRIMARY KEY, base TEXT NOT NULL, cliente_id BIGINT NOT NULL, nombre TEXT, fecha DATE NOT NULL,
  resultado TEXT NOT NULL, nota TEXT, proxima DATE, por TEXT, creado TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS vendedor_seg_cli ON vendedor_seguimientos (base, cliente_id, creado);
CREATE TABLE IF NOT EXISTS vendedor_telefonos (base TEXT NOT NULL, cliente_id BIGINT NOT NULL, telefono TEXT NOT NULL, por TEXT,
  creado TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (base, cliente_id));
CREATE TABLE IF NOT EXISTS reactivacion_cola (id BIGSERIAL PRIMARY KEY, tipo TEXT NOT NULL, ref TEXT NOT NULL, telefono TEXT NOT NULL, nombre TEXT,
  detalle TEXT, prioridad INT NOT NULL DEFAULT 5, creado TIMESTAMPTZ NOT NULL DEFAULT now(), estado TEXT NOT NULL DEFAULT 'pendiente',
  intento TIMESTAMPTZ, enviado TIMESTAMPTZ, lead_id BIGINT, resultado TEXT, UNIQUE (tipo, ref));
CREATE TABLE IF NOT EXISTS tablero_cierres (mes DATE NOT NULL, base TEXT NOT NULL, datos JSONB NOT NULL, utilidad NUMERIC, bono NUMERIC, total NUMERIC,
  autorizo TEXT, fecha_pago DATE, por TEXT, creado TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (mes, base));
CREATE TABLE IF NOT EXISTS ms_costos_manual (base TEXT, articulo_id BIGINT, costo NUMERIC, por TEXT, actualizado TIMESTAMPTZ DEFAULT now(), PRIMARY KEY (base, articulo_id));
ALTER TABLE ms_articulos ADD COLUMN IF NOT EXISTS costo_ultimo NUMERIC;
CREATE TABLE IF NOT EXISTS tablero_perfiles (clave TEXT PRIMARY KEY, nombre TEXT NOT NULL, almacenes TEXT NOT NULL DEFAULT '', grupos TEXT NOT NULL DEFAULT '', usuarios_web TEXT NOT NULL DEFAULT '', usuarios_ms TEXT NOT NULL DEFAULT '', activo BOOLEAN NOT NULL DEFAULT true, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
SELECT c->>'rol' AS rol, c->>'nombre' AS nombre, c->'perfil' AS perfil, c->'perfiles' AS perfiles, c->'usuarios_web' AS usuarios_web FROM (SELECT vw_tablero_ctx($1, $2) AS c) z;

