// Arma los datos del tablero del vendedor: metas con su premio, objetivo de hoy, contra el mes pasado,
// clientes por recuperar (regla: pasó su umbral Y lleva más de 1.5 veces su ciclo), seguimientos, cotizaciones, productos y monedero.
const cfg = $('Vendedor · Configuración').first().json;
const rol = String($('Vendedor · Acceso').first().json.rol || '');
const r = $('Vendedor · Leer datos').first().json.r || {};
if (!r.hoy) { const e = $('Vendedor · Leer datos').first().json.error; return [{ json: { respuesta: { ok: false, msg: 'No se pudieron leer las ventas' + (e ? ': ' + String(e.message || e).slice(0, 200) : '') } } }]; }
const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const C = Object.assign({}, cfg, r.cfg || {});
const DH = Math.min(7, Math.max(5, Number(C.dias_habiles_semana) || 6));
const KG = Number(C.kg_por_bulto) || 50;
const iso = d => d.toISOString().slice(0, 10);
const D = s => new Date(String(s).slice(0, 10) + 'T12:00:00Z');
const hoy = String(r.hoy).slice(0, 10);
const H = D(hoy), Y = H.getUTCFullYear(), M = H.getUTCMonth(), DIA = H.getUTCDate();
const N = new Date(Date.UTC(Y, M + 1, 0)).getUTCDate(), NA = new Date(Date.UTC(Y, M, 0)).getUTCDate();
const fechaDe = (y, m, d) => iso(new Date(Date.UTC(y, m, d, 12)));
const dow = f => { const w = D(f).getUTCDay(); return w === 0 ? 7 : w; };
// días que no se trabajan (festivos) y cuánto vale cada día: lunes a viernes = 1; el sábado vale lo que de verdad se vende en sábado
const FEST = new Set(String(C.dias_no_laborables || '').split(/[,;\s]+/).filter(x => /^\d{4}-\d{2}-\d{2}$/.test(x)));
const habil = f => dow(f) <= DH && !FEST.has(f);
const PROM = r.dow_prom || {};
const promSemana = [1, 2, 3, 4, 5].map(i => num(PROM[i])).filter(x => x > 0);
const satAuto = promSemana.length && num(PROM[6]) > 0 ? num(PROM[6]) / (promSemana.reduce((a, b) => a + b, 0) / promSemana.length) : 0.68;
const satManual = num(C.peso_sabado);
const SAT = Math.min(1.2, Math.max(0.3, satManual ?? satAuto));
const w = f => habil(f) ? (dow(f) === 6 ? SAT : 1) : 0;
const MES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const DSEM = ['', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];

// ---------- ventas y cemento por día ----------
const porFecha = {};
for (const d of r.dias || []) porFecha[String(d.fecha).slice(0, 10)] = { venta: num(d.venta) || 0, ton: num(d.ton) || 0, b25: num(d.b25) || 0, b50: num(d.b50) || 0 };
const val = (f, k) => (porFecha[f] || {})[k] || 0;
let habMes = 0, habAntes = 0, nHabMes = 0, nHabHastaHoy = 0;   // habMes/habAntes en "días completos" (el sábado vale SAT)
const acum = { venta: 0, ton: 0, b25: 0, b50: 0 }, ayer = { venta: 0, ton: 0, b25: 0, b50: 0 };
for (let d = 1; d <= N; d++) {
  const f = fechaDe(Y, M, d);
  if (habil(f)) { habMes += w(f); nHabMes++; if (d < DIA) habAntes += w(f); if (d <= DIA) nHabHastaHoy++; }
  if (d <= DIA) for (const k of ['venta', 'ton', 'b25', 'b50']) { acum[k] += val(f, k); if (d < DIA) ayer[k] += val(f, k); }
}
const habRest = Math.max(0.3, habMes - habAntes);                     // días por delante (en días completos), contando hoy
const nHabRest = Math.max(1, nHabMes - nHabHastaHoy + (habil(hoy) ? 1 : 0));
const esperado = Math.min(1, (habAntes + w(hoy)) / Math.max(0.3, habMes));
// contra el mes pasado: hasta el mismo número de día hábil (hoy es el día hábil nHabHastaHoy del mes)
const ant = { venta: { mismo: 0, cierre: 0 }, ton: { mismo: 0, cierre: 0 } };
let cuentaAnt = 0, corteAnt = null;
for (let d = 1; d <= NA; d++) { const f = fechaDe(Y, M - 1, d); if (habil(f)) { cuentaAnt++; if (cuentaAnt <= nHabHastaHoy) corteAnt = f; } }
if (nHabHastaHoy > cuentaAnt) corteAnt = fechaDe(Y, M - 1, NA);
for (let d = 1; d <= NA; d++) { const f = fechaDe(Y, M - 1, d); for (const k of ['venta', 'ton']) { ant[k].cierre += val(f, k); if (corteAnt && f <= corteAnt) ant[k].mismo += val(f, k); } }

// ---------- metas del mes (las captura el administrador en el tablero de ventas) ----------
const metas = r.metas || {};
const metaVenta = num(metas.venta) || 0;
const metaTon = num(metas.cemento_ton) ?? num(C.meta_cemento_ton) ?? 0;
const metaAltas = num(metas.monedero_altas) || 0;
const metaRec = num(metas.recuperados) || 0;
const bultos = t => Math.round(t * 1000 / KG);
const ventaHoy = val(hoy, 'venta'), tonHoy = val(hoy, 'ton');
const objHoy = metaVenta ? Math.max(0, metaVenta - ayer.venta) * w(hoy) / habRest : 0;
const bultosObjHoy = metaTon ? Math.ceil(Math.max(0, metaTon - ayer.ton) * 1000 / KG * w(hoy) / habRest) : 0;

// ---------- clientes por recuperar ----------
const umbral = seg => seg === 'Reventa' ? (num(C.dias_sin_comprar_reventa) || 10) : (num(C.dias_sin_comprar_publico) || 15);
const factor = num(C.factor_ciclo) || 1.5;
const TEL = r.telefonos || {};
const BOT = {}; for (const b of r.bot || []) if (b.tel) BOT[String(b.tel)] = String(b.fecha).slice(0, 10);
const cand = (r.recuperar || []).map(c => {
  const tel = String(c.tel || TEL[c.cid] || '').replace(/\D/g, '').slice(-10);
  return { id: c.cid, n: c.nombre, tipo: c.seg, dias: num(c.dias) || 0, ciclo: num(c.cada), anual: num(c.venta12) || 0,
    tel: tel.length === 10 ? tel : '', tags: [...(num(c.ton6) > 0 ? ['cemento'] : []), ...(c.monedero ? ['monedero'] : [])],
    bot: tel ? (BOT[tel] || null) : null };
});
const clientes = cand.filter(c => c.id && c.ciclo && c.dias >= Math.max(umbral(c.tipo), Math.round(factor * c.ciclo))).slice(0, 40);
const fuera = cand.length - cand.filter(c => c.id && c.ciclo && c.dias >= Math.max(umbral(c.tipo), Math.round(factor * c.ciclo))).length;

// seguimientos del vendedor (los guarda la página)
const seguimientos = {};
for (const s of r.seguimientos || []) {
  const k = String(s.cliente_id);
  const x = seguimientos[k] || (seguimientos[k] = { contactos: [], proxima: null });
  x.contactos.push({ fecha: String(s.fecha).slice(0, 10), resultado: s.resultado, nota: s.nota || '', por: s.por || '' });
  x.proxima = s.proxima ? String(s.proxima).slice(0, 10) : null;   // vienen en orden: el último manda
}
for (const k in seguimientos) seguimientos[k].contactos = seguimientos[k].contactos.slice(-10);

// clientes que regresaron: solo cuentan si estuvieron fuera al menos N días (30 por omisión)
const minFuera = num(C.dias_minimos_recuperado) || 30;
const compraMin = num((r.metas || {}).compra_min_recuperado) ?? num(C.compra_min_recuperado) ?? 0;
const recuperados = (r.recuperados || []).filter(x => (num(x.dias_fuera) || 0) >= minFuera && (num(x.venta) || 0) >= compraMin)
  .map(x => ({ n: x.nombre, dias_fuera: num(x.dias_fuera), volvio: String(x.volvio).slice(0, 10) }));
const recHoy = recuperados.filter(x => x.volvio === hoy).length;

// ---------- monedero ----------
const mon = r.monedero || {};
const altasMes = num(mon.altas_mes) || 0, altasHoy = num(mon.altas_hoy) || 0;

// ---------- productos y categorías (contra el mes pasado al mismo día) ----------
const pct = (a, b) => b > 0 ? a / b - 1 : (a > 0 ? null : 0);
const categorias = (r.categorias || []).map(c => ({ n: c.cat, act: num(c.act) || 0, ant: num(c.ant) || 0 }))
  .map(c => ({ ...c, pct: pct(c.act, c.ant) }));
const productos = (r.productos || []).map(p => {
  const act = num(p.act) || 0, a = num(p.ant) || 0, x = pct(act, a), exi = num(p.exi);
  let tip;
  if (exi !== null && exi <= 0 && act > 0) tip = 'Se vende y no hay en almacén: avisa para pedir.';
  else if (x === null || x >= 0.05) tip = 'Va bien. Ofrécelo a quien lleve material.';
  else if (act === 0) tip = 'Este mes no se ha vendido. Ofrécelo en cada visita.';
  else if (x <= -0.1) tip = 'Va mal. Pregunta a tus clientes si lo necesitan.';
  else tip = 'Va igual que el mes pasado.';
  return { cat: p.cat, n: p.nombre, act, ant: a, pct: x, tip, sin_exi: exi !== null && exi <= 0 && act > 0 };
});

// ---------- cotizaciones abiertas ----------
const cotizaciones = (r.cotizaciones || []).map(c => {
  const tel = String(c.tel || TEL[c.cliente_id] || '').replace(/\D/g, '').slice(-10);
  return { folio: c.folio, fecha: String(c.fecha).slice(0, 10), total: num(c.total) || 0, cliente: c.cliente,
    tel: tel.length === 10 ? tel : '', dias: Math.round((H - D(c.fecha)) / 864e5) };
});

// ---------- la semana (lunes a sábado, dentro del mes) ----------
// Meta de la semana = lo que faltaba del mes al empezar la semana, repartido entre los días hábiles que quedaban.
// Se fija al inicio de la semana: si cumple cada semana, cumple el mes.
const addD = (f, n) => iso(new Date(D(f).getTime() + n * 864e5));
const lunes = addD(hoy, -(dow(hoy) - 1));
const iniMes = fechaDe(Y, M, 1), finMes = fechaDe(Y, M, N);
const semIni = lunes < iniMes ? iniMes : lunes;
const semFinW = addD(lunes, DH - 1), semFin = semFinW > finMes ? finMes : semFinW;
const rango = (a, b) => { const out = []; for (let f = a; f <= b; f = addD(f, 1)) out.push(f); return out; };
const sw = (a, b) => rango(a, b).reduce((t, f) => t + w(f), 0);
const habSem = sw(semIni, semFin);
const habSemAntes = sw(semIni, addD(hoy, -1));
const habSemRest = Math.max(0.3, habSem - habSemAntes);
const habDesdeSem = sw(semIni, finMes);
const esperadoSem = Math.min(1, (habSemAntes + w(hoy)) / Math.max(0.3, habSem));
const ALTAS = r.altas_dias || {};
const REC = {}; for (const x of recuperados) REC[x.volvio] = (REC[x.volvio] || 0) + 1;
const serie = { venta: f => val(f, 'venta'), ton: f => val(f, 'ton'), clientes: f => REC[f] || 0, monedero: f => num(ALTAS[f]) || 0 };
const suma = (fn, a, b) => rango(a, b).reduce((t, f) => t + fn(f), 0);
function semana(fn, metaMes, entero) {
  const antes = suma(fn, iniMes, addD(semIni, -1));
  const falta = Math.max(0, metaMes - antes);
  let meta = habDesdeSem ? falta * habSem / habDesdeSem : 0;
  if (entero) meta = falta > 0 ? Math.max(1, Math.ceil(meta)) : 0;
  const lleva = suma(fn, semIni, hoy), antesHoy = suma(fn, semIni, addD(hoy, -1)), hoyV = fn(hoy);
  return { meta, lleva, hoy: hoyV, obj_hoy: Math.max(0, meta - antesHoy) * w(hoy) / habSemRest };
}
const sb = x => ({ ...x, meta: Math.ceil(x.meta * 1000 / KG), lleva: bultos(x.lleva), hoy: bultos(x.hoy), obj_hoy: Math.ceil(x.obj_hoy * 1000 / KG) });
const SEM = {
  cemento: sb(semana(serie.ton, metaTon, false)),
  venta: (x => ({ ...x, meta: Math.round(x.meta / 100) * 100 }))(semana(serie.venta, metaVenta, false)),
  clientes: semana(serie.clientes, metaRec, true),
  monedero: semana(serie.monedero, metaAltas, true),
};
const MESC = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const semanaTxt = `del ${D(semIni).getUTCDate()} al ${D(semFin).getUTCDate()} de ${MESC[M]}`;

const PESO_DEF = { cemento: 35, venta: 25, clientes: 30, monedero: 10 };
const peso = k => (num(metas['peso_' + k]) ?? num(C['peso_' + k]) ?? PESO_DEF[k]) / 100;
const actualizado = String(r.actualizado || '');
// ---------- bono de la política: utilidad de los grupos del bono × 5 %; encargado 80 % (por metas), chofer 20 % ----------
const U = (r.util || {}).mes || {};
const margenEst = num(U.venta_cc) ? (num(U.venta_cc) - num(U.costo)) / num(U.venta_cc) : null;
const utilEst = margenEst !== null ? num(U.venta) * margenEst : null;          // se extrapola a la venta sin costo conocido
const utilOf = num(metas.utilidad_oficial);
const utilidad = utilOf !== null ? utilOf : (utilEst || 0);
const pctB = (num(C.bono_pct) ?? 5) / 100, pE = (num(C.parte_encargado) ?? 80) / 100, pC = (num(C.parte_chofer) ?? 20) / 100;
const bonoTotal = Math.max(0, utilidad) * pctB;
const extras = [
  { id: 'desempeno', t: 'Desempeño', monto: num(C.premio_desempeno) ?? 500, ok: num(metas.ok_desempeno) === 1 },
  { id: 'puntualidad', t: 'Puntualidad', monto: num(C.premio_puntualidad) ?? 300, ok: num(metas.ok_puntualidad) === 1 },
];
const hoyReal = new Date(Date.now() - 6 * 3600000).toISOString().slice(0, 10);
const respuesta = {
  ok: true, rol, puede_bono: rol === 'admin',
  perfil: $('Vendedor · Acceso').first().json.perfil || null, perfiles: $('Vendedor · Acceso').first().json.perfiles || null, quien: String($('Vendedor · Acceso').first().json.nombre || ''),
  opciones: rol === 'admin' ? { almacenes: r.opc_almacenes || [], grupos: r.opc_grupos || [], usuarios_ms: r.opc_usuarios_ms || [], usuarios_web: $('Vendedor · Acceso').first().json.usuarios_web || [] } : null,
  negocio: C.nombre_tienda || 'Construrama Lomas Ajusco', vendedor: C.vendedor || 'Vendedor',
  hoy_iso: hoy, dia_txt: `${DSEM[dow(hoy)]} ${DIA} de ${MES[M]}`, mes_txt: MES[M], corte: actualizado.slice(11, 16),
  esperado, dias_rest: habRest, bono: Math.round(bonoTotal * pE * 100) / 100,
  bono_info: { utilidad, oficial: utilOf !== null, util_est: utilEst, margen_est: margenEst, venta_grupos: num(U.venta) || 0, pct: pctB, parte_encargado: pE, parte_chofer: pC,
    bono_total: bonoTotal, chofer: bonoTotal * pC, nombre_chofer: C.nombre_chofer || 'Chofer', grupos: r.grupos_bono || [] },
  extras, puede_extras: rol === 'admin' || rol === 'supervisor', puede_cerrar: rol === 'admin', vista_pasada: hoy < hoyReal, mes_iso: iniMes,
  cierres: (rol === 'admin' || rol === 'supervisor') ? (r.cierres || []) : [], peso_sabado: Math.round(SAT * 100) / 100, sabado_auto: satManual == null,
  hoy_peso: w(hoy), festivos: [...FEST].sort(),
  esperado_sem: esperadoSem, dias_rest_sem: habSemRest, semana_txt: semanaTxt,
  hoy: { venta: ventaHoy, objetivo: objHoy, bultos: bultos(tonHoy), bultos_obj: bultosObjHoy, b25: val(hoy, 'b25'), b50: val(hoy, 'b50') },
  cemento_mes: { b25: acum.b25, b50: acum.b50 }, kg_bulto: KG,
  cemento_articulos: rol === 'admin' ? (r.cemento_articulos || []).map(a => ({ clave: a.clave, nombre: a.nombre, kg: num(a.kg), uds: num(a.uds_mes) || 0 })) : [],
  compara: { mes_act: MES[M], mes_ant: MES[(M + 11) % 12], dia: Math.min(DIA, NA), dia_habil: nHabHastaHoy,
    corte_ant: corteAnt, corte_ant_txt: corteAnt ? DSEM[dow(corteAnt)].slice(0, 3).toLowerCase() + ' ' + D(corteAnt).getUTCDate() : '',
    venta: { act: acum.venta, mismo: ant.venta.mismo, cierre: ant.venta.cierre },
    ton: { act: acum.ton, mismo: ant.ton.mismo, cierre: ant.ton.cierre } },
  metas: [
    { id: 'cemento', t: 'Cemento Tolteca', peso: peso('cemento'), lleva: bultos(acum.ton), meta: bultos(metaTon), hoy: bultos(tonHoy), u: 'bultos', premioDe: 'cemento', vis: 'truck' },
    { id: 'venta', t: 'Venta materiales y ferretería', peso: peso('venta'), lleva: acum.venta, meta: metaVenta, hoy: ventaHoy, u: 'money', premioDe: 'venta', vis: 'runner' },
    { id: 'clientes', t: 'Recuperar clientes', peso: peso('clientes'), lleva: recuperados.length, meta: metaRec, hoy: recHoy, u: 'clientes', premioDe: 'clientes recuperados', vis: 'people' },
    { id: 'monedero', t: 'Altas de monedero', peso: peso('monedero'), lleva: altasMes, meta: metaAltas, hoy: altasHoy, u: 'altas', premioDe: 'monedero', vis: 'jar' },
  ].map(m => ({ ...m, sem: SEM[m.id] })),
  config: rol === 'admin' ? (() => {
    const pack = (mm, mesIni) => ({ mes: mesIni, venta: num(mm.venta), cemento_ton: num(mm.cemento_ton), monedero_altas: num(mm.monedero_altas),
      recuperados: num(mm.recuperados), bono: num(mm.bono), compra_min_recuperado: num(mm.compra_min_recuperado),
      peso_cemento: num(mm.peso_cemento), peso_venta: num(mm.peso_venta), peso_clientes: num(mm.peso_clientes), peso_monedero: num(mm.peso_monedero) });
    const sig = fechaDe(Y, M + 1, 1);
    return { actual: { ...pack(metas, iniMes), cemento_ton: metaTon || null, compra_min_recuperado: compraMin,
               peso_cemento: Math.round(peso('cemento') * 100), peso_venta: Math.round(peso('venta') * 100), peso_clientes: Math.round(peso('clientes') * 100), peso_monedero: Math.round(peso('monedero') * 100) },
             siguiente: pack(r.metas_sig || {}, sig), mes_act: MES[M], mes_sig: MES[(M + 1) % 12], kg: KG,
             dias_reventa: num(C.dias_sin_comprar_reventa) || 10, dias_publico: num(C.dias_sin_comprar_publico) || 15,
             festivos: [...FEST].sort(), peso_sabado: satManual, sabado_auto: Math.round(satAuto * 100) / 100, dias_semana: DH };
  })() : null,
  clientes, fuera, seguimientos, recuperados, meta_recuperados: metaRec,
  cotizaciones, categorias, productos,
  monedero: { altas_mes: altasMes, altas_hoy: altasHoy, meta: metaAltas },
};
// ---------- pedidos nuevos de construcción (sin tinacos) ----------
const pd = r.pedidos || {};
respuesta.pedidos = { hoy_n: num(pd.hoy_n) || 0, hoy_monto: num(pd.hoy_monto) || 0, mes_n: num(pd.mes_n) || 0, mes_monto: num(pd.mes_monto) || 0,
  ant_n: num(pd.ant_n) || 0, ant_monto: num(pd.ant_monto) || 0,
  lista: (pd.lista || []).map(x => ({ folio: x.folio, fecha: String(x.fecha).slice(0, 10), cliente: x.cliente, total: num(x.total) || 0 })) };

// ---------- plan del día con IA: uno en la mañana y otro después de la 1 pm ----------
const horaMX = new Date(Date.now() - 6 * 3600000).getUTCHours();
const franja = horaMX < 13 ? 'manana' : 'tarde';
const iaOn = String(C.ia_activa ?? 'true') === 'true' && habil(hoy) && hoy >= hoyReal;
const p0 = r.plan || null;
respuesta.plan = p0 && p0.plan ? { ...p0.plan, hora: p0.hora } : null;
const needPlan = iaOn && (!p0 || p0.franja !== franja);
let prompt = '';
if (needPlan) {
  const pctTxt = (a, b) => b ? Math.round(a / b * 100) + '%' : 'sin meta';
  const datos = {
    vendedor: respuesta.vendedor, dia: respuesta.dia_txt, hora: horaMX + ':00', dias_habiles_que_faltan: nHabRest,
    nota_sabado: 'el sábado se abre medio día; su meta es ' + Math.round(SAT * 100) + '% de un día normal',
    deberia_ir_al_cerrar_hoy: Math.round(esperado * 100) + '% de cada meta',
    metas: respuesta.metas.filter(m => m.meta > 0).map(m => ({ meta: m.t, lleva: Math.round(m.lleva), de: Math.round(m.meta), avance: pctTxt(m.lleva, m.meta), hoy: Math.round(m.hoy), unidad: m.u === 'money' ? 'pesos' : m.u })),
    hoy: { venta: Math.round(ventaHoy), objetivo_venta: Math.round(objHoy), bultos: bultos(tonHoy), objetivo_bultos: bultosObjHoy, bultos_50kg: val(hoy, 'b50'), bultos_25kg: val(hoy, 'b25') },
    contra_mes_pasado_misma_fecha: { venta: Math.round(acum.venta) + ' vs ' + Math.round(ant.venta.mismo), cemento_ton: acum.ton.toFixed(1) + ' vs ' + ant.ton.mismo.toFixed(1) },
    clientes_por_llamar: clientes.slice(0, 8).map(c => { const sg = seguimientos[String(c.id)]; const u = sg && sg.contactos[sg.contactos.length - 1];
      return { cliente: c.n, tipo: c.tipo, dias_sin_venir: c.dias, compraba_cada: c.ciclo, compraba_al_mes: Math.round(c.anual / 12), compra_cemento: c.tags.includes('cemento'),
        tiene_telefono: !!c.tel, bot_ya_le_escribio: !!c.bot, ultimo_contacto: u ? u.resultado + (u.nota ? ' (' + u.nota + ')' : '') : null,
        toca_seguimiento_hoy: !!(sg && sg.proxima && sg.proxima <= hoy) }; }),
    cotizaciones_abiertas: cotizaciones.slice(0, 5).map(c => ({ cliente: c.cliente, total: c.total, hace_dias: c.dias })),
    productos_para_activar: productos.filter(p => p.ant > 0 && p.pct !== null && p.pct <= -0.1).sort((a, b) => (b.ant - b.act) - (a.ant - a.act)).slice(0, 5).map(p => ({ producto: p.n, este_mes: p.act, mes_pasado_misma_fecha: p.ant })),
    productos_que_van_bien: productos.filter(p => p.act > 0 && (p.pct === null || p.pct >= 0.05)).sort((a, b) => b.act - a.act).slice(0, 5).map(p => ({ producto: p.n, este_mes: p.act, sin_existencia: p.sin_exi })),
    pedidos_nuevos_construccion: { hoy: respuesta.pedidos.hoy_n, mes: respuesta.pedidos.mes_n, mes_pasado_misma_fecha: respuesta.pedidos.ant_n },
    monedero_altas: { hoy: altasHoy, mes: altasMes, meta: metaAltas },
  };
  prompt = JSON.stringify(datos);
}
return [{ json: { respuesta, need_plan: needPlan, prompt, franja, base: String(r.mb || C.base || r.base || ''), modelo: String(C.modelo_ia || 'gpt-4.1-mini') } }];

// Revisa lo que manda la página antes de guardar: seguimiento de un cliente, teléfono nuevo o monto del bono (solo administrador)
const cfg = $('Vendedor · Configuración').first().json;
const rol = String($('Vendedor · Acceso').first().json.rol || '');
const b = $('Vendedor · API').first().json.body || {};
const op = String(b.op || '');
const fail = msg => [{ json: { ok: false, msg } }];
const hoyMX = new Date(Date.now() - 6 * 3600000);                 // Ciudad de México (UTC-6, sin horario de verano)
const hoy = hoyMX.toISOString().slice(0, 10);
const base = String(cfg.base || '');
const acc = $('Vendedor · Acceso').first().json, pf = acc.perfil || null;
const mb = pf && pf.clave ? base + '#' + pf.clave : base;     // las metas, el bono y los cierres son de cada perfil
const por = String(acc.nombre || (rol === 'admin' ? 'admin' : (cfg.vendedor || rol)));
let metasJ = '{}', confJ = '{}', perfJ = '{}';
let cid = '', nombre = '', resultado = '', nota = '', proxima = '', tel = '', monto = '', mes = '';
if (op === 'contacto' || op === 'telefono') {
  const x = Number(b.cliente_id);
  if (!Number.isInteger(x) || x <= 0) return fail('Cliente inválido.');
  cid = String(x); nombre = String(b.nombre || '').slice(0, 120);
}
if (op === 'contacto') {
  const ok = ['compra', 'despues', 'precio', 'otro', 'nocontesta', 'no'];
  resultado = String(b.resultado || '');
  if (!ok.includes(resultado)) return fail('Escoge qué te dijo el cliente.');
  nota = String(b.nota || '').replace(/\s+/g, ' ').trim().slice(0, 300);
  const dias = Number(b.dias);
  if (!Number.isInteger(dias) || dias < 0 || dias > 60) return fail('Escoge cuándo lo vuelves a contactar.');
  if (dias > 0) { const p = new Date(hoyMX.getTime() + dias * 864e5); proxima = p.toISOString().slice(0, 10); }
} else if (op === 'telefono') {
  tel = String(b.telefono || '').replace(/\D/g, '');
  if (tel.length !== 10) return fail('El número debe tener 10 dígitos.');
} else if (op === 'bono') {
  if (rol !== 'admin') return fail('Solo el administrador puede cambiar el bono.');
  const m = Number(String(b.monto ?? '').replace(/[$,\s]/g, ''));
  if (!isFinite(m) || m < 0 || m > 1e7) return fail('Revisa el monto del bono.');
  monto = String(m); mes = hoy.slice(0, 8) + '01';
} else if (op === 'config') {
  if (rol !== 'admin') return fail('Solo el administrador puede cambiar metas.');
  const ini = hoy.slice(0, 8) + '01';
  const sigD = new Date(Date.UTC(+hoy.slice(0, 4), +hoy.slice(5, 7), 1)); const sig = sigD.toISOString().slice(0, 10);
  mes = String(b.mes || '');
  if (mes !== ini && mes !== sig) return fail('Solo se puede configurar este mes o el siguiente.');
  const m = b.metas || {}, out = {};
  const numero = (k, max) => { const t = String(m[k] ?? '').replace(/[$,\s]/g, ''); if (t === '') return true; const x = Number(t); if (!isFinite(x) || x < 0 || x > max) return false; out[k] = String(x); return true; };
  for (const [k, max] of [['venta', 1e9], ['cemento_ton', 1e5], ['monedero_altas', 1e5], ['recuperados', 1e4], ['bono', 1e7], ['compra_min_recuperado', 1e7]])
    if (!numero(k, max)) return fail('Revisa el valor de ' + k.replace(/_/g, ' ') + '.');
  let suma = 0;
  for (const k of ['peso_cemento', 'peso_venta', 'peso_clientes', 'peso_monedero']) {
    const x = Number(m[k]); if (!Number.isInteger(x) || x < 0 || x > 100) return fail('Los porcentajes deben ser enteros de 0 a 100.');
    out[k] = String(x); suma += x;
  }
  if (suma !== 100) return fail('Los porcentajes deben sumar 100. Hoy suman ' + suma + '.');
  const g = {};
  for (const [k, kk] of [['dias_reventa', 'dias_sin_comprar_reventa'], ['dias_publico', 'dias_sin_comprar_publico']]) {
    const x = Number(b[k]); if (!Number.isInteger(x) || x < 5 || x > 365) return fail('Los días sin comprar deben ser de 5 a 365.'); g[kk] = String(x);
  }
  const fest = (Array.isArray(b.festivos) ? b.festivos : []).map(String).filter(x => /^\d{4}-\d{2}-\d{2}$/.test(x));
  if (fest.length > 60) return fail('Son demasiados días festivos.');
  g.dias_no_laborables = [...new Set(fest)].sort().join(',');
  const ps = String(b.peso_sabado ?? '').trim();
  if (ps === '') g.peso_sabado = '';
  else { const x = Number(ps); if (!isFinite(x) || x < 20 || x > 120) return fail('El sábado debe valer entre 20% y 120% de un día normal.'); g.peso_sabado = String(Math.round(x) / 100); }
  metasJ = JSON.stringify(out); confJ = JSON.stringify(g);
} else if (op === 'extra') {
  if (rol !== 'admin' && rol !== 'supervisor') return fail('Solo administración puede marcar desempeño y puntualidad.');
  const clave = String(b.clave || ''); if (!['ok_desempeno', 'ok_puntualidad'].includes(clave)) return fail('Opción inválida.');
  mes = String(b.mes || ''); if (!/^\d{4}-\d{2}-01$/.test(mes) || mes > hoy.slice(0, 8) + '01') return fail('Mes inválido.');
  metasJ = JSON.stringify({ [clave]: b.valor ? '1' : '0' });
} else if (op === 'utilidad') {
  if (rol !== 'admin') return fail('Solo el administrador captura la utilidad oficial.');
  mes = String(b.mes || ''); if (!/^\d{4}-\d{2}-01$/.test(mes) || mes > hoy.slice(0, 8) + '01') return fail('Mes inválido.');
  const t = String(b.utilidad ?? '').replace(/[$,\s]/g, '');
  if (t !== '' && (!isFinite(Number(t)) || Number(t) < 0 || Number(t) > 1e8)) return fail('Revisa la utilidad.');
  metasJ = JSON.stringify({ utilidad_oficial: t });
} else if (op === 'cerrar') {
  if (rol !== 'admin') return fail('Solo el administrador puede cerrar el mes.');
  mes = String(b.mes || ''); if (!/^\d{4}-\d{2}-01$/.test(mes) || mes > hoy.slice(0, 8) + '01') return fail('Mes inválido.');
  const d = b.datos && typeof b.datos === 'object' ? b.datos : null;
  if (!d) return fail('Faltan los datos del cierre.');
  if (!(Number(d.utilidad) > 0)) return fail('Captura la utilidad oficial del reporte «Margen de utilidad» de Microsip.');
  if (!String(d.autorizo || '').trim()) return fail('Escribe quién autoriza.');
  if (d.fecha_pago && !/^\d{4}-\d{2}-\d{2}$/.test(String(d.fecha_pago))) return fail('Fecha de pago inválida.');
  const js = JSON.stringify(d); if (js.length > 20000) return fail('Cierre demasiado grande.');
  monto = String(Math.round(Number(d.total_encargado || 0) * 100) / 100); metasJ = js;
} else if (op === 'perfil_guardar' || op === 'perfil_borrar') {
  if (rol !== 'admin') return fail('Solo el administrador puede cambiar los perfiles.');
  const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 30);
  const nom = String(b.nombre || '').replace(/\s+/g, ' ').trim().slice(0, 60);
  const clave = String(b.clave || '').replace(/[^a-z0-9-]/g, '').slice(0, 30) || (op === 'perfil_guardar' ? slug(nom) : '');
  if (!clave) return fail(op === 'perfil_borrar' ? 'Falta el perfil.' : 'Ponle un nombre al perfil.');
  if (op === 'perfil_guardar' && !nom) return fail('Ponle un nombre al perfil.');
  const lista = (t, sep) => [...new Set(String(t || '').split(/[,;|\n]+/).map(x => x.replace(/\s+/g, ' ').trim()).filter(Boolean))].join(sep).slice(0, 300);
  perfJ = JSON.stringify({ clave, nombre: nom, almacenes: lista(b.almacenes, ','), grupos: lista(b.grupos, '|'), usuarios_web: lista(b.usuarios_web, ','), usuarios_ms: lista(b.usuarios_ms, ','), activo: b.activo === false ? false : true });
} else return fail('Acción desconocida.');
return [{ json: { ok: true, op, proxima, p: [op, base, cid, nombre, resultado, nota, proxima, por, tel, monto, mes, metasJ, confJ, mb, perfJ] } }];

// Lee la respuesta de la IA, la limpia y la agrega a los datos de la página. Si la IA falla, la página sigue sin plan.
const a = $('Vendedor · Armar datos').first().json;
const respuesta = { ...a.respuesta };
let plan = null;
try {
  const txt = (($json.choices || [])[0] || {}).message?.content || '';
  const p = JSON.parse(txt);
  const acciones = (Array.isArray(p.acciones) ? p.acciones : []).slice(0, 3)
    .map(x => ({ icono: String(x.icono || '👉').slice(0, 4), texto: String(x.texto || '').replace(/\s+/g, ' ').trim().slice(0, 240) }))
    .filter(x => x.texto);
  if (acciones.length) plan = { saludo: String(p.saludo || '').slice(0, 160), acciones, frase: String(p.frase || '').slice(0, 160) };
} catch (e) {}
const hora = new Date(Date.now() - 6 * 3600000).toISOString().slice(11, 16);
respuesta.plan = plan ? { ...plan, hora } : respuesta.plan;
return [{ json: { respuesta, guardar: plan ? 'true' : 'false', plan: JSON.stringify(plan || {}), franja: a.franja, fecha: respuesta.hoy_iso || '', base: a.base } }];

