  'TEXCOCO': [19.511, -98.882], 'ATENCO': [19.556, -98.917], 'ACOLMAN': [19.635, -98.912], 'GUSTAVO A. MADERO': [19.482, -99.113],
  'GUSTAVO A MADERO': [19.482, -99.113], 'ECATEPEC': [19.601, -99.050], 'COACALCO': [19.629, -99.110], 'TULTITLAN': [19.645, -99.169],
  'TULTEPEC': [19.685, -99.128], 'CUAUTITLAN': [19.655, -99.195], 'CUAUTITLAN IZCALLI': [19.646, -99.211], 'TEOLOYUCAN': [19.745, -99.181],
  'ZUMPANGO': [19.796, -99.099], 'TECAMAC': [19.713, -98.968], 'HUEHUETOCA': [19.834, -99.204], 'SANTIAGO TIANGUISTENCO': [19.180, -99.468]
};
const REGION_EXTRA = { 'TEXCOCO': 'ORIENTE', 'ATENCO': 'ORIENTE', 'CHICOLOAPAN': 'ORIENTE', 'VALLE DE CHALCO': 'ORIENTE', 'LA PAZ': 'ORIENTE',
  'TEOLOYUCAN': 'NORTE', 'TULTEPEC': 'NORTE', 'CUAUTITLAN IZCALLI': 'NORTE', 'GUSTAVO A MADERO': 'NORTE', 'SANTIAGO TIANGUISTENCO': 'FORANEO' };
const normZ = s => String(s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
// nombres de zona escritos de varias formas (con acento, abreviados, con errores de dedo) → siempre el mismo nombre de la lista de zonas
const ZALIAS = { 'GUSTAVO': 'GUSTAVO A. MADERO', 'GAM': 'GUSTAVO A. MADERO', 'GUSTAVO A MADERO': 'GUSTAVO A. MADERO', 'NEZA': 'NEZAHUALCOYOTL', 'CUAHUTEMOC': 'CUAUHTEMOC', 'CUAUTEMOC': 'CUAUHTEMOC',
  'TLANEPANTLA': 'TLALNEPANTLA', 'TLALNEPATLA': 'TLALNEPANTLA', 'MAGADALENA CONTRERAS': 'MAGDALENA CONTRERAS', 'MIGUEL HIDLAGO': 'MIGUEL HIDALGO', 'ATIZAPAN': 'ATIZAPAN DE ZARAGOZA',
  'LOS REYES': 'LOS REYES LA PAZ', 'IZCALLI': 'CUAUTITLAN IZCALLI', 'ALVARO OBREGON': 'ALVARO OBREGON', 'A OBREGON': 'ALVARO OBREGON', 'V CARRANZA': 'VENUSTIANO CARRANZA' };
const lev = (a, b) => { const d = Array.from({ length: a.length + 1 }, (_, i) => [i]); for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); return d[a.length][b.length]; };
const zonaKey = z => { let n = normZ(z); const nn = n.replace(/[.,;:]/g, ' ').replace(/\s+/g, ' ').trim(); if (ZONAS[n]) return n; if (ZALIAS[nn]) return ZALIAS[nn]; if (ZONAS[nn]) return nn;
  const k = Object.keys(ZONAS).find(x => nn.includes(x) || (nn.length >= 5 && x.startsWith(nn)));
  if (k) return k;
  if (nn.length >= 6) { const ks = Object.keys(ZONAS).map(x => ({ x, d: lev(nn, x) })).filter(o => o.d <= (nn.length >= 9 ? 2 : 1)).sort((a, b) => a.d - b.d); if (ks.length) return ks[0].x; }
  return n; };
const zonaNom = z => { const t = String(z || ''); if (/[·\/]/.test(t)) return t; const k = zonaKey(t); return ZONAS[k] ? k : t.replace(/[\s.,;:]+$/, '').toUpperCase(); };
// coordenadas escritas en la liga de Google Maps (si las trae)
const coordsDeUrl = u => { const m = String(u || '').match(/(?:@|q=|ll=|query=|destination=)(-?\d{1,2}\.\d{3,}),\s*(-?\d{2,3}\.\d{3,})/) || String(u || '').match(/!3d(-?\d{1,2}\.\d+)!4d(-?\d{2,3}\.\d+)/);
  return m ? [Number(m[1]), Number(m[2])] : null; };
const km = (a, b) => { const R = 6371, r = x => x * Math.PI / 180; const dLa = r(b[0] - a[0]), dLo = r(b[1] - a[1]);
  const h = Math.sin(dLa / 2) ** 2 + Math.cos(r(a[0])) * Math.cos(r(b[0])) * Math.sin(dLo / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };
// minutos de manejo: distancia por calle ≈ 1.35 × línea recta; 22 km/h en ciudad, 35 km/h en tramos largos (periférico, autopista)
// + margen por tráfico / imprevistos (margen_trafico_pct, 10 % si no se pone)
const minutos = (a, b, cfg) => { const d = km(a, b) * Number(cfg.factor_calle || 1.35); const v = d > 15 ? Number(cfg.vel_carretera || 35) : Number(cfg.vel_ciudad || 22);
  return Math.round(d / v * 60 * (1 + Number(cfg.margen_trafico_pct ?? 10) / 100)); };
const hhmm = m => { m = Math.round(m); return String(Math.floor(m / 60) % 24).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };
const durTxt = m => { m = Math.round(m); return m >= 60 ? `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, '0')} min` : `${m} min`; };
// ordena paradas por "la más cercana sigue" saliendo de la base; los que reciben en la mañana van primero y los de la tarde al final
const rangoV = p => !p.ventana ? 1 : p.ventana.hasta && !p.ventana.desde ? 0 : p.ventana.desde && p.ventana.desde >= 780 ? 2 : 1;
const ordenar = (base, ps) => { const rest = ps.slice(), out = []; let cur = base;
  while (rest.length) { let bi = 0, bd = Infinity; rest.forEach((p, i) => { const d = p.coord ? km(cur, p.coord) : 999; if (d < bd) { bd = d; bi = i; } });
    const p = rest.splice(bi, 1)[0]; out.push(p); if (p.coord) cur = p.coord; }
  return out.map((p, i) => ({ p, i })).sort((a, b) => rangoV(a.p) - rangoV(b.p) || a.i - b.i).map(x => x.p); };
// horarios estimados de cada parada desde una hora de salida (minutos del día).
// Entrega: min_por_entrega (descarga y cobro) + min_por_tinaco_extra por cada tinaco más. Si el cliente recibe "después de las X", se espera.
const servDe = (p, cfg) => p.pickup ? Number(cfg.min_recoger_cisterna || 30) : (p.unidades ? Number(cfg.min_por_entrega || 15) + Number(cfg.min_por_tinaco_extra ?? 5) * Math.max(0, Math.ceil(p.unidades) - 1) : 0) + (p.servicio ? Number(cfg.min_servicio || 30) : 0) || Number(cfg.min_por_entrega || 15);
const tiempos = (base, ps, salida, cfg) => { let t = salida, cur = base, kmT = 0;
  const r = ps.map(p => { const c = p.coord || cur; const viaje = minutos(cur, c, cfg); kmT += km(cur, c) * Number(cfg.factor_calle || 1.35); t += viaje;
    let espera = 0; if (p.ventana && p.ventana.desde && t < p.ventana.desde) { espera = p.ventana.desde - t; t = p.ventana.desde; }
    const o = { llegada: t, viaje, espera, fuera: !!(p.ventana && p.ventana.hasta && t > p.ventana.hasta) }; t += servDe(p, cfg); cur = c; return o; });
  const regreso = minutos(cur, base, cfg); kmT += km(cur, base) * Number(cfg.factor_calle || 1.35);
  return { paradas: r, fin_ultima: t, regreso_base: t + regreso, km: Math.round(kmT) }; };
// ---- fin del bloque compartido ----
// ===== Asistente de rutas v2: calcula la propuesta y la entrega a la página web o como resumen por Telegram =====
// [clave, grupo, etiqueta, tipo, ayuda]
const AJUSTES = [
  ['mezclar_si_sobra', 'Camionetas y jornada', 'Si una camioneta va con lugar, ¿puede llevar otra región aunque no sea vecina?', 'sino', 'si = no deja pedidos fuera mientras haya lugar y regrese antes de la hora máxima (lo marca como mezcla)'],
