if (quitados.length) resumen.push(`➖ <b>Se quitaron de la ruta</b> (se les borró chofer y día en la hoja): ${quitados.join(', ')}`);
const quien = body.oficial ? ' (ruta oficial ajustada a mano)' : body.simulada ? ' (simulación ajustada a mano)' : '';
return [{ json: {
  ok: true, fecha: T, dia: DIA,
  hayR: datosR.length > 0, hayN: nuevas.length > 0, hayP: datosP.length > 0,
  cuerpoR: { valueInputOption: 'RAW', data: datosR },
  cuerpoN: { values: nuevas }, rangoN: `'${HOJA_R}'!A${ultima + 1}`,
  cuerpoP: { valueInputOption: 'RAW', data: datosP },
  renglones: datosR.length / 2, quitados, agregados: yaNuevo.size, pedidos: datosP.length / 2, faltan: [...new Set(faltan)], avisos: [...new Set(avisos)],
  resumen, quien, token: cfg.token_oficina, chat: String(cfg.chat_rutas || ''),
  detalle: JSON.stringify({ fecha: T, simulada: !!body.simulada, viajes })
} }];

// Junta lo que pasó al escribir en las hojas y arma la respuesta para la página y el aviso de Telegram
const prep = $('Rutas · Preparar cambios').first().json;
if (!prep.ok) return [{ json: { ok: false, msg: prep.msg || 'No se pudo confirmar.' } }];
const res = n => { try { return $(n).first().json; } catch (e) { return null; } };
const errs = [];
for (const [n, q] of [['Rutas · Escribir hoja de rutas', 'hoja de rutas'], ['Rutas · Agregar a la hoja de rutas', 'renglones nuevos'], ['Rutas · Escribir hoja pedidos', 'hoja pedidos']]) {
  const r = res(n); if (r && r.error) errs.push(`${q}: ${String((r.error && (r.error.message || r.error.description)) || r.error).slice(0, 160)}`); }
const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const etq = `${DIAS[new Date(prep.fecha + 'T12:00:00Z').getUTCDay()]} ${prep.dia.slice(0, 5)}`;
const hecho = [`${prep.renglones} renglón(es) con chofer y día ${prep.dia}`, prep.agregados && `${prep.agregados} pedido(s) agregados a la hoja de rutas`, prep.pedidos && `${prep.pedidos} renglón(es) en la hoja pedidos`].filter(Boolean).join(', ');
const faltan = prep.faltan.length ? ` No encontré en la hoja: ${prep.faltan.join(', ')}.` : '';
const ok = errs.length === 0;
if (prep.tipo === 'resultado') {
  const c = prep.cuenta || {}, cu = `✅ ${c.entregado || 0} entregados · ❌ ${c.no_entregado || 0} no entregados · 📅 ${c.reprogramado || 0} reprogramados${c.cancelado ? ' · 🚫 ' + c.cancelado + ' cancelados' : ''}`;
  const extra = [...prep.avisos, ...(prep.faltan.length ? [`No encontré en la hoja: ${prep.faltan.join(', ')} (solo se guardó el resultado)`] : [])];
  const msg = ok ? `Resultado del ${etq} guardado: ${cu}.${c.no_entregado ? ' Los no entregados ya quedaron libres y el plan los mete primero.' : ''}${extra.length ? ' ' + extra.join(' · ') : ''}` : `Se guardó solo una parte. Revisa la hoja. Falló: ${errs.join(' · ')}`;
  const T2 = [`${ok ? '📋' : '⚠️'} <b>Resultado de entregas · ${etq}</b>`, cu, ...prep.resumen, ...extra.map(x => '⚠️ ' + x)];
  // desde el tablero de Salidas (silencioso): marcar «entregado» no manda Telegram; solo avisa cuando alguien no se entregó, se reprogramó o se canceló, o si algo falló
  const quieto = !!((($('Rutas · API').first().json || {}).body || {}).silencioso);
  const avisar = !(ok && quieto && !(c.no_entregado || c.reprogramado || c.cancelado));
  return [{ json: { ok, msg, tipo: 'resultado', avisar, token: prep.token, cuerpo: { chat_id: prep.chat, parse_mode: 'HTML', disable_web_page_preview: true, text: T2.join('\n').replace(/&(?![a-z]+;)/g, '&amp;').slice(0, 3900) }, fecha: prep.fecha, detalle: prep.detalle } }];
}
if (prep.tipo === 'servicio') {
  const msg = ok ? `Servicio agregado a la hoja de rutas para el ${etq}. Ya aparece en la propuesta de ese día.` : `No se pudo agregar el servicio: ${errs.join(' · ')}`;
  return [{ json: { ok, msg, token: prep.token, cuerpo: { chat_id: prep.chat, parse_mode: 'HTML', disable_web_page_preview: true, text: `${ok ? '➕' : '⚠️'} <b>Servicio para el ${etq}</b>\n${prep.resumen.join('\n')}`.slice(0, 3900) }, fecha: prep.fecha, detalle: prep.detalle } }];
}
const msg = ok ? `Ruta del ${etq} confirmada: ${hecho}. El bot de avisos les manda la fecha a los clientes.${faltan}${prep.avisos.length ? ' ' + prep.avisos.join(' ') : ''}`
  : `Se escribió solo una parte. Revisa la hoja. Falló: ${errs.join(' · ')}`;
const L = [`${ok ? '✅' : '⚠️'} <b>Ruta confirmada · ${etq}</b>${prep.quien}`, ...prep.resumen, '', `📝 ${hecho}.`];
if (faltan) L.push(`⚠️${faltan}`);
if (!ok) L.push(`❌ Falló: ${errs.join(' · ')}`);
return [{ json: { ok, msg, token: prep.token, cuerpo: { chat_id: prep.chat, parse_mode: 'HTML', disable_web_page_preview: true, text: L.join('\n').replace(/&(?![a-z]+;)/g, '&amp;').slice(0, 3900) },
  fecha: prep.fecha, detalle: prep.detalle } }];

