CREATE TABLE IF NOT EXISTS rutas_disponibilidad (fecha DATE PRIMARY KEY, camionetas JSONB NOT NULL DEFAULT '{}'::jsonb, choferes INT, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO rutas_disponibilidad (fecha, camionetas, choferes, actualizado) VALUES ($1::date, $2::jsonb, NULLIF($3, '')::int, now())
ON CONFLICT (fecha) DO UPDATE SET camionetas = EXCLUDED.camionetas, choferes = EXCLUDED.choferes, actualizado = now() RETURNING fecha;

CREATE TABLE IF NOT EXISTS rutas_config (clave TEXT PRIMARY KEY, valor TEXT, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
DELETE FROM rutas_config WHERE clave = ANY(string_to_array(NULLIF($2, ''), ','));
INSERT INTO rutas_config (clave, valor, actualizado) SELECT key, value, now() FROM jsonb_each_text($1::jsonb)
ON CONFLICT (clave) DO UPDATE SET valor = EXCLUDED.valor, actualizado = now() RETURNING clave;

CREATE TABLE IF NOT EXISTS rutas_disponibilidad (fecha DATE PRIMARY KEY, camionetas JSONB NOT NULL DEFAULT '{}'::jsonb, choferes INT, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
SELECT coalesce(json_object_agg(fecha::text, json_build_object('camionetas', camionetas, 'choferes', choferes)), '{}'::json) AS d
FROM rutas_disponibilidad WHERE fecha >= (now() AT TIME ZONE 'America/Mexico_City')::date - 1;

CREATE TABLE IF NOT EXISTS ubicaciones_folio (folio TEXT PRIMARY KEY, url TEXT, por TEXT, actualizado TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS ubicaciones_geo (clave TEXT PRIMARY KEY, direccion TEXT, lat DOUBLE PRECISION, lng DOUBLE PRECISION, fuente TEXT, nivel TEXT, intentos INT NOT NULL DEFAULT 0, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
SELECT coalesce(json_object_agg(k, u), '{}'::json) AS u FROM (
  SELECT clave AS k, 'q=' || lat || ',' || lng || CASE WHEN nivel IN ('colonia', 'cp') THEN '&aprox' ELSE '' END AS u FROM ubicaciones_geo WHERE lat IS NOT NULL
  UNION ALL
  SELECT upper(regexp_replace(folio, '\s', '', 'g')), url FROM ubicaciones_folio WHERE url ~ '[0-9]{1,2}[.][0-9]{3,}'
) x;

CREATE TABLE IF NOT EXISTS rutas_borradores (fecha DATE PRIMARY KEY, viajes JSONB NOT NULL, sacados JSONB, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
DELETE FROM rutas_borradores WHERE fecha < (now() AT TIME ZONE 'America/Mexico_City')::date - 1;
SELECT coalesce(json_object_agg(fecha::text, json_build_object('viajes', viajes, 'sacados', coalesce(sacados, '[]'::jsonb),
         'actualizado', to_char(actualizado AT TIME ZONE 'America/Mexico_City', 'DD/MM HH24:MI'))), '{}'::json) AS b FROM rutas_borradores;

