// ===== Análisis semanal de rutas: junta los números de la semana, ajusta solos los tiempos que se midieron y arma la pregunta para la IA =====
const AJ = (() => { try { return ($('Rutas · Ajustes guardados').first().json || {}).a || {}; } catch (e) { return {}; } })();
const cfg = Object.assign({}, $('Rutas · Configuración').first().json, Object.fromEntries(Object.entries(AJ).filter(([, v]) => String(v ?? '') !== '')));
const X = (() => { try { const j = $('Rutas · Datos de la semana').first().json || {}; return j.x || {}; } catch (e) { return {}; } })();
const HOY = X.hoy || new Date(Date.now() - 6 * 3600000).toISOString().slice(0, 10);
const DIA = 86400000, menos = n => new Date(new Date(HOY + 'T12:00:00Z').getTime() - n * DIA).toISOString().slice(0, 10);
const ini = menos(7), iniAnt = menos(14);
const aMin = h => { const m = String(h || '').match(/(\d{1,2}):(\d{2})/); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };
const HMAX = aMin(cfg.hora_max_regreso) ?? 1110;
const viajes = X.viajes || [], paradas = X.paradas || [], res = X.resultados || [];
const llave = f => { const n = (String(f || '').toUpperCase().match(/^P\s*0*(\d{3,})/) || [])[1]; return n ? 'P' + n : String(f || '').toUpperCase().replace(/\s+/g, ''); };
const cap1 = s => String(s || '').charAt(0) + String(s || '').slice(1).toLowerCase();
const med = a => { if (!a.length) return null; const s = a.slice().sort((x, y) => x - y), m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const r1 = n => n == null ? null : Math.round(n);
// ---- números de una semana ----
const semana = (d0, d1) => {
  const V = viajes.filter(v => v.fecha >= d0 && v.fecha < d1), Pp = paradas.filter(p => p.fecha >= d0 && p.fecha < d1), Rr = res.filter(r => r.fecha >= d0 && r.fecha < d1);
  const resDe = {}; Rr.forEach(r => { resDe[r.fecha + '|' + llave(r.folio)] = r; });
  const cnt = { entregado: 0, no_entregado: 0, reprogramado: 0, cancelado: 0 }; Rr.forEach(r => { cnt[r.resultado] = (cnt[r.resultado] || 0) + 1; });
  // si la oficina no lo marcó pero el chofer sí (en su página), cuenta lo del chofer
  const soloChofer = Pp.filter(p => p.folio && !resDe[p.fecha + '|' + llave(p.folio)] && p.chofer_marco);
  soloChofer.forEach(p => { if (/(^|,)entregado/.test(p.chofer_marco)) cnt.entregado++; else cnt.no_entregado++; });
  const sinMarcar = Pp.filter(p => p.folio && !resDe[p.fecha + '|' + llave(p.folio)] && !p.chofer_marco).length;
  const porCh = {}; V.forEach(v => { const c = porCh[v.chofer] = porCh[v.chofer] || { viajes: 0, km: 0, paradas: 0, tarde_est: 0, tarde_real: 0, no_entregados: 0 };
    c.viajes++; c.km += Number(v.km) || 0; c.paradas += Number(v.paradas) || 0; if (aMin(v.regreso) > HMAX) c.tarde_est++; if (aMin(v.fin_real) > HMAX) c.tarde_real++; });
  Rr.filter(r => r.resultado !== 'entregado').forEach(r => { const c = porCh[r.chofer] = porCh[r.chofer] || { viajes: 0, km: 0, paradas: 0, tarde_est: 0, tarde_real: 0, no_entregados: 0 }; c.no_entregados++; });
  const motivos = {}, zonas = {}; Rr.filter(r => r.resultado !== 'entregado').forEach(r => { motivos[r.motivo || 'sin motivo'] = (motivos[r.motivo || 'sin motivo'] || 0) + 1; zonas[r.zona || '¿?'] = (zonas[r.zona || '¿?'] || 0) + 1; });
  const regDif = V.filter(v => aMin(v.fin_real) != null && aMin(v.regreso) != null).map(v => aMin(v.fin_real) - aMin(v.regreso));
  return { desde: d0, hasta_sin_incluir: d1, dias: new Set(V.map(v => v.fecha)).size, viajes: V.length, km: Math.round(V.reduce((s, v) => s + (Number(v.km) || 0), 0)),
    costo: Math.round(V.reduce((s, v) => s + (Number(v.costo) || 0), 0)), tinacos: Math.round(V.reduce((s, v) => s + (Number(v.tinacos) || 0), 0)), entregas_planeadas: Pp.length,
    ...cnt, sin_marcar: sinMarcar, pct_entregado: Pp.length ? Math.round(cnt.entregado / Pp.length * 100) : null,
    regresos_tarde_estimados: V.filter(v => aMin(v.regreso) > HMAX).length, regresos_tarde_reales: V.filter(v => aMin(v.fin_real) > HMAX).length,
    regreso_real_vs_estimado_min: r1(med(regDif)), rutas_con_regreso_real: regDif.length, por_chofer: porCh,
    motivos: Object.entries(motivos).sort((a, b) => b[1] - a[1]), zonas_con_fallas: Object.entries(zonas).sort((a, b) => b[1] - a[1]).slice(0, 6) };
};
const S = semana(ini, HOY), Sa = semana(iniAnt, ini);
// ---- tiempos reales (últimos 14 días): cuánto tarda de verdad cada entrega y cuánto se atrasa la llegada contra lo estimado ----
const desc = paradas.map(p => Number(p.descarga)).filter(n => n > 0 && n < 180);
const lleg = paradas.filter(p => p.llegue && p.hora).map(p => aMin(p.llegue) - aMin(p.hora)).filter(n => Math.abs(n) < 240);
const MIN_ENT = Number(cfg.min_por_entrega || 15), MARGEN = Number(cfg.margen_trafico_pct ?? 10);
const tiempos = { descarga_real_min: r1(med(desc)), entregas_medidas: desc.length, min_por_entrega: MIN_ENT, llegada_vs_estimado_min: r1(med(lleg)), llegadas_medidas: lleg.length, margen_trafico_pct: MARGEN };
// ---- ajustes automáticos (solo tiempos, con suficientes mediciones y en pasos chicos); se apagan con ajuste_automatico = no ----
let web = false; try { $('Rutas · API').first(); web = true; } catch (e) {}
// desde la página ("Analizar ahora") solo se muestran; se aplican en el análisis automático del lunes
const AUTO = String(cfg.ajuste_automatico ?? 'si').toLowerCase() !== 'no', MIN_N = 12, ajustes = {}, ajustesTxt = [];
if (AUTO && desc.length >= MIN_N) { const real = med(desc), dif = real - MIN_ENT;
  if (Math.abs(dif) >= 3) { const nuevo = Math.max(10, Math.min(45, Math.round(MIN_ENT + Math.max(-5, Math.min(5, dif)))));
    if (nuevo !== MIN_ENT) { ajustes.min_por_entrega = String(nuevo); ajustesTxt.push(`Minutos por entrega: ${MIN_ENT} → <b>${nuevo}</b> (la descarga real tardó ${Math.round(real)} min en ${desc.length} entregas medidas)`); } } }
// el margen de tráfico solo se mueve si no se movieron los minutos por entrega (una cosa a la vez, para no pasarse)
if (AUTO && lleg.length >= MIN_N && !ajustes.min_por_entrega) { const d = med(lleg); let nuevo = MARGEN;
  if (d >= 10) nuevo = Math.min(40, MARGEN + 5); else if (d <= -15) nuevo = Math.max(0, MARGEN - 5);
  if (nuevo !== MARGEN) { ajustes.margen_trafico_pct = String(nuevo); ajustesTxt.push(`Margen por tráfico: ${MARGEN}% → <b>${nuevo}%</b> (los choferes llegaron ${d > 0 ? Math.round(d) + ' min después' : Math.round(-d) + ' min antes'} de lo estimado, ${lleg.length} llegadas medidas)`); } }
const hayDatos = S.viajes > 0 || res.some(r => r.fecha >= ini);
const datos = { semana: S, semana_anterior: Sa, tiempos, hora_max_regreso: cfg.hora_max_regreso || '18:30', capacidad: cfg.capacidad_por_chofer || '', choferes: cfg.choferes || '', ajustes_automaticos: ajustes,
  ajustes_semana_pasada: (X.previo || {}).ajustes || null };
const SYS = 'Eres el analista de logística de Super Tank (tinacos y cisternas, CDMX y Edomex). Dos camionetas (Walas y Martín) salen de Lomas Ajusco; un solo viaje al día; las cisternas grandes se recogen en Chalco. ' +
  'Con los números de la semana, explica en español claro y corto qué pasó y propone mejoras CONCRETAS a la ruta (qué zonas juntar o separar, qué días, horarios, qué pedidos llamar antes, qué revisar con cada chofer). ' +
  'No inventes números: usa solo los que vienen. No repitas los ajustes automáticos como recomendación. Si hay pocos datos (por ejemplo muchos "sin_marcar"), dilo y pide que se marquen los resultados. ' +
  'Responde SOLO un JSON: {"resumen": "2 o 3 frases", "hallazgos": ["máximo 5, cada uno con su número"], "recomendaciones": [{"accion": "qué hacer", "por_que": "dato que lo justifica"}] (máximo 4)}';
const req = { model: 'gpt-4.1', temperature: 0.2, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(datos) }] };
return [{ json: { req, datos, ajustes: web ? {} : ajustes, ajustesTxt, aplica: !web, hayDatos, web, ini, fin: menos(1), token: cfg.token_oficina, chat: String(cfg.chat_rutas || '') } }];

// ===== Arma el mensaje del análisis semanal (números calculados aquí + lo que dice la IA) =====
const P = $('Rutas · Preparar análisis').first().json, S = P.datos.semana, Sa = P.datos.semana_anterior, Tm = P.datos.tiempos;
const e = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dm = f => String(f || '').slice(8, 10) + '/' + String(f || '').slice(5, 7);
const cap1 = s => String(s || '').charAt(0) + String(s || '').slice(1).toLowerCase();
let ia = null, iaErr = '';
try { const r = $('Rutas · IA analiza la semana').first().json || {}; if (r.error) iaErr = String(r.error.message || r.error).slice(0, 120);
  const c = r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content; if (c) ia = JSON.parse(c); } catch (err) { iaErr = iaErr || 'respuesta no válida'; }
const vs = (a, b, u = '') => b ? ` (${a >= b ? '+' : ''}${a - b}${u} vs. semana anterior)` : '';
const L = [`🧠 <b>Análisis de rutas · ${dm(P.ini)} al ${dm(P.fin)}</b>`];
if (!P.hayDatos) L.push('', 'Esta semana no hay rutas confirmadas ni resultados marcados: no hay qué analizar. Confirmen las rutas y marquen el resultado de cada día en la página.');
else {
  L.push('', `📦 ${S.entregas_planeadas} entregas en ruta · ✅ ${S.entregado}${S.pct_entregado != null ? ' (' + S.pct_entregado + '%)' : ''} · ❌ ${S.no_entregado} · 📅 ${S.reprogramado}${S.cancelado ? ' · 🚫 ' + S.cancelado : ''}${S.sin_marcar ? ' · ⏳ <b>' + S.sin_marcar + ' sin marcar</b>' : ''}`);
  L.push(`🚚 ${S.viajes} viajes · ${S.km} km${vs(S.km, Sa.km, ' km')}${S.costo ? ' · $' + S.costo.toLocaleString('es-MX') : ''} · regresos después de las ${e(P.datos.hora_max_regreso)}: ${S.regresos_tarde_reales || S.regresos_tarde_estimados}${S.rutas_con_regreso_real ? ' (reales)' : ' (estimados)'}`);
  const ch = Object.entries(S.por_chofer || {}); if (ch.length) L.push('👷 ' + ch.map(([n, c]) => `${cap1(n)}: ${c.viajes} viajes, ${Math.round(c.km)} km${c.no_entregados ? ', ' + c.no_entregados + ' no entregados o reprogramados' : ''}`).join(' · '));
  if (S.motivos.length) L.push('❌ Por qué no se entregó: ' + S.motivos.map(([m, n]) => `${e(m)} (${n})`).join(' · '));
  if (S.zonas_con_fallas.length) L.push('📍 Zonas con fallas: ' + S.zonas_con_fallas.map(([z, n]) => `${e(z)} (${n})`).join(' · '));
  if (Tm.entregas_medidas || Tm.llegadas_medidas) L.push(`⏱️ Tiempos reales (14 días): ${Tm.entregas_medidas ? 'descarga ~' + Tm.descarga_real_min + ' min (configurado ' + Tm.min_por_entrega + ', ' + Tm.entregas_medidas + ' medidas)' : ''}${Tm.entregas_medidas && Tm.llegadas_medidas ? ' · ' : ''}${Tm.llegadas_medidas ? 'llegan ' + (Tm.llegada_vs_estimado_min >= 0 ? Tm.llegada_vs_estimado_min + ' min después' : -Tm.llegada_vs_estimado_min + ' min antes') + ' de lo estimado (' + Tm.llegadas_medidas + ' medidas)' : ''}`);
  if (P.ajustesTxt.length) L.push('', P.aplica ? '🔧 <b>Ajusté solo</b> (para que las próximas rutas calculen mejor):' : '🔧 <b>El lunes se ajustará solo</b> (con los datos de ese día):', ...P.ajustesTxt.map(t => '• ' + t), P.aplica ? 'Si no te parece, regrésalo en la página → Ajustes.' : '');
  if (ia) { if (ia.resumen) L.push('', '💡 ' + e(ia.resumen));
    (ia.hallazgos || []).slice(0, 5).forEach(h => L.push('• ' + e(h)));
    if ((ia.recomendaciones || []).length) { L.push('', '✅ <b>Para mejorar la ruta:</b>'); ia.recomendaciones.slice(0, 4).forEach((r, i) => L.push(`${i + 1}. ${e(r.accion)}${r.por_que ? ' — <i>' + e(r.por_que) + '</i>' : ''}`)); } }
  else L.push('', `(La IA no respondió${iaErr ? ': ' + e(iaErr) : ''}; van solo los números.)`);
}
const texto = L.join('\n').slice(0, 3900);
return [{ json: { ok: true, texto, web: P.web, msg: 'Análisis listo y enviado al chat de rutas por Telegram.', semana: P.ini, datos: JSON.stringify({ ...P.datos, ia }), ajustes: JSON.stringify(P.ajustes || {}),
  token: P.token, cuerpo: { chat_id: P.chat, parse_mode: 'HTML', disable_web_page_preview: true, text: texto } } }];

