// Ubicación que capturó la oficina para un pedido: liga de Google Maps, liga de WhatsApp o coordenadas «19.30, -99.16»
const b = $('Rutas · API').first().json.body || {};
const txt = String(b.url || '').trim();
const folios = [...new Set([b.folio, b.folio2].map(x => String(x || '').trim().toUpperCase().replace(/\s+/g, '')).filter(Boolean))];
const co = s => { const m = String(s || '').match(/(-?\d{1,2}\.\d{3,})\s*,\s*(-?\d{2,3}\.\d{3,})/) || String(s || '').match(/@(-?\d{1,2}\.\d{3,}),(-?\d{2,3}\.\d{3,})/) || String(s || '').match(/!3d(-?\d{1,2}\.\d{3,})!4d(-?\d{2,3}\.\d{3,})/); return m ? [m[1], m[2]] : null; };
const c = co(txt), liga = (txt.match(/https?:\/\/\S+/) || [''])[0];
return [{ json: { folios, txt, liga, coord: c, resolver: !c && !!liga, url: c ? `https://www.google.com/maps/search/?api=1&query=${c[0]},${c[1]}` : liga } }];

// Las ligas cortas (maps.app.goo.gl) redirigen a una liga larga que sí trae las coordenadas
const p = $('Rutas · Preparar ubicación').first().json, r = $input.first().json || {};
const h = r.headers || {}, loc = h.location || h.Location || '';
const co = s => { const m = String(s || '').match(/@(-?\d{1,2}\.\d{3,}),(-?\d{2,3}\.\d{3,})/) || String(s || '').match(/!3d(-?\d{1,2}\.\d{3,})!4d(-?\d{2,3}\.\d{3,})/) || String(s || '').match(/[?&](?:q|query|ll)=(-?\d{1,2}\.\d{3,}),\s*(-?\d{2,3}\.\d{3,})/); return m ? [m[1], m[2]] : null; };
const c = co(loc) || co(typeof r.body === 'string' ? r.body.slice(0, 20000) : '');
return [{ json: { ...p, coord: c, url: c ? `https://www.google.com/maps/search/?api=1&query=${c[0]},${c[1]}` : p.liga } }];

