CREATE TABLE IF NOT EXISTS ubicaciones_folio (folio TEXT PRIMARY KEY, url TEXT, por TEXT, actualizado TIMESTAMPTZ DEFAULT now());
INSERT INTO ubicaciones_folio (folio, url, por, actualizado)
SELECT f, $2, 'planeador', now() FROM jsonb_array_elements_text($1::jsonb) f WHERE coalesce($2, '') <> ''
ON CONFLICT (folio) DO UPDATE SET url = EXCLUDED.url, por = EXCLUDED.por, actualizado = now();
SELECT 1 AS ok;

CREATE TABLE IF NOT EXISTS rutas_zonas (zona TEXT PRIMARY KEY, region TEXT NOT NULL, actualizado TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO rutas_zonas (zona, region) SELECT upper(btrim(x->>'zona')), upper(btrim(x->>'region')) FROM jsonb_array_elements('{{ JSON.stringify($('Rutas · Leer zonas').all().map(i => { const r = i.json || {}, ks = Object.keys(r); const z = r[ks.find(k => /^zona/i.test(k.trim()))], g = r[ks.find(k => /regi/i.test(k))]; return z && g ? { zona: String(z).trim(), region: String(g).trim() } : null; }).filter(Boolean)).replace(/'/g, "''") }}'::jsonb) x WHERE coalesce(btrim(x->>'zona'),'') <> '' AND coalesce(btrim(x->>'region'),'') <> '' ON CONFLICT (zona) DO NOTHING;
SELECT json_build_object('z', (SELECT coalesce(json_agg(json_build_object('zona', zona, 'region', region)), '[]'::json) FROM rutas_zonas)) AS x;
